(function(){
'use strict';
const db=new FakeBackend();if(window.__ussV3Boot)window.__ussV3Boot(db);window.__ussDb=db;
const app=document.getElementById('app');
let charts=[];
let replayTimer=null;
const allNav=[
 ['Overview','dashboard','bi-grid-1x2-fill'],['Platform','tenants','bi-buildings-fill'],['Organization','organization','bi-diagram-3'],['People','users','bi-people-fill'],['Endpoint Fleet','devices','bi-pc-display-horizontal'],['Activity Explorer','activity','bi-clock-history'],['Workforce Intelligence','workforce','bi-bar-chart-fill'],['Behavioral Risk','risk','bi-activity'],['Alerts','alerts','bi-exclamation-triangle-fill'],['DLP & Sensitive Data','dlp','bi-file-earmark-lock-fill'],['Policies & Automation','policies','bi-bezier2'],['Investigations','investigations','bi-search-heart'],['Reports & Search','reports','bi-file-earmark-bar-graph'],['AI Copilot','ai','bi-stars'],['Privacy & Governance','privacy','bi-eye-slash-fill'],['Audit Trail','audit','bi-journal-check'],['Integrations','integrations','bi-plug-fill'],['Employee Transparency','transparency','bi-person-check-fill'],['Platform Settings','settings','bi-gear-fill'],['Editions','editions','bi-boxes'],['Coverage Matrix','coverage','bi-radar'],['Risk Ledger','ledger','bi-journal-richtext'],['Observation Levels','observation','bi-layers'],['Legal Hold','legalhold','bi-lock-fill'],['AI Governance','aigov','bi-robot'],['Jurisdiction','jurisdiction','bi-globe2'],['Golden Scenarios','golden','bi-trophy']
];
const roleRoutes={
 super_admin:['dashboard','tenants','organization','users','devices','reports','audit','integrations','settings','editions','coverage','golden'],
 company_admin:['dashboard','organization','users','devices','activity','workforce','risk','alerts','dlp','policies','investigations','reports','privacy','audit','integrations','settings','editions','coverage','observation','jurisdiction','golden','ledger'],
 it_admin:['dashboard','organization','users','devices','activity','policies','reports','audit','integrations','settings','coverage','observation','golden'],
 manager:['dashboard','users','activity','workforce','reports','ai','coverage','settings'],hr:['dashboard','users','workforce','reports','ai','privacy','jurisdiction','settings'],
 soc:['dashboard','users','devices','activity','risk','alerts','dlp','policies','investigations','reports','ai','audit','integrations','ledger','observation','coverage','golden','aigov','legalhold','settings'],
 risk:['dashboard','users','activity','risk','alerts','investigations','reports','ai','audit','ledger','observation','golden','coverage','settings'],
 dlp:['dashboard','users','activity','risk','alerts','dlp','policies','investigations','reports','audit','ledger','aigov','golden','observation','settings'],
 investigator:['dashboard','users','activity','risk','alerts','investigations','reports','ai','audit','ledger','legalhold','observation','golden','settings'],
 legal:['dashboard','users','investigations','reports','audit','legalhold','jurisdiction','golden','settings'],compliance:['dashboard','users','dlp','policies','investigations','reports','privacy','audit','jurisdiction','legalhold','golden','coverage','settings'],
 auditor:['dashboard','reports','privacy','audit','golden','jurisdiction','settings'],privacy:['dashboard','users','policies','privacy','audit','reports','observation','jurisdiction','coverage','golden','aigov','settings'],
 executive:['dashboard','workforce','risk','reports','ai','editions','ledger','golden','coverage','settings'],employee:['dashboard','transparency','settings']
};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const route=()=>location.hash.replace('#/','').split('?')[0]||'dashboard';
const params=()=>new URLSearchParams(location.hash.split('?')[1]||'');
const persona=()=>db.get('personas').find(p=>p.id===db.persona())||db.get('personas')[0];
const userName=id=>db.user(id)?.name||id;
const riskClass=s=>s==='Critical'?'risk-critical':s==='High'?'risk-high':s==='Medium'?'risk-medium':'risk-low';
const badge=(txt,cls='status-online')=>`<span class="badge-soft ${cls}">${esc(txt)}</span>`;
const metric=(label,val,trend,icon)=>`<div class="card-soft metric"><div class="d-flex justify-content-between"><div class="metric-label">${esc(label)}</div><i class="bi ${icon} text-secondary"></i></div><div class="metric-value mt-2">${esc(val)}</div><div class="metric-trend text-secondary mt-1">${esc(trend)}</div></div>`;
function destroyCharts(){charts.forEach(c=>{try{c.destroy()}catch(e){}});charts=[];}
function toast(msg,title='USS Prototype'){const id='t'+Date.now();document.getElementById('toastHost').insertAdjacentHTML('beforeend',`<div id="${id}" class="toast show" role="alert"><div class="toast-header"><strong class="me-auto">${esc(title)}</strong><button class="btn-close" data-bs-dismiss="toast"></button></div><div class="toast-body">${esc(msg)}</div></div>`);setTimeout(()=>document.getElementById(id)?.remove(),3800);}
function download(name,content,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){if(!rows.length)return '';const keys=Object.keys(rows[0]);const q=v=>'"'+String(v??'').replace(/"/g,'""')+'"';return [keys.map(q).join(','),...rows.map(r=>keys.map(k=>q(r[k])).join(','))].join('\n');}
function showModal(title,body,footer='',size='lg'){
 document.getElementById('dynModal')?.remove();
 document.body.insertAdjacentHTML('beforeend',`<div class="modal fade" id="dynModal" tabindex="-1"><div class="modal-dialog modal-${size} modal-dialog-centered modal-dialog-scrollable modal-fullscreen-sm-down"><div class="modal-content"><div class="modal-header"><h5 class="modal-title">${title}</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer flex-wrap gap-2">${footer}</div>`:''}</div></div></div>`);
 const el=document.getElementById('dynModal'),m=new bootstrap.Modal(el);el.addEventListener('hidden.bs.modal',()=>{if(replayTimer){clearInterval(replayTimer);replayTimer=null;}el.remove();});m.show();return m;
}
function closeModal(){const el=document.getElementById('dynModal');if(el)bootstrap.Modal.getInstance(el)?.hide();}
function head(title,sub,actions=''){return `<div class="page-head d-flex justify-content-between align-items-start gap-3 mb-4"><div class="min-w-0"><h2 class="page-title mb-1">${esc(title)}</h2><div class="page-subtitle">${esc(sub)}</div></div><div class="page-actions d-flex flex-wrap gap-2">${actions}</div></div>`;}
function login(){const ps=db.get('personas');app.innerHTML=`<div class="login-page"><div class="login-card"><div class="row g-0"><div class="col-lg-5 login-aside"><div class="d-flex align-items-center gap-3 mb-5"><div class="brand-mark">USS</div><div><div class="fw-bold fs-5">Behavioral Visibility</div><small class="opacity-75">High-Fidelity Functional Prototype v3</small></div></div><h1 class="display-6 fw-bold">Experience stakeholder workflows end to end.</h1><p class="opacity-75 mt-3">Interactive fake backend, persistent state, working CRUD, investigations, DLP, policy simulation, privacy approvals, reports and scenario-driven risk changes.</p><div class="mt-4 small opacity-75"><i class="bi bi-check2-circle me-2"></i>Persistent local fake backend<br><i class="bi bi-check2-circle me-2"></i>Role-based workspaces<br><i class="bi bi-check2-circle me-2"></i>Working investigation tabs & replay<br><i class="bi bi-check2-circle me-2"></i>GitHub Pages compatible</div></div><div class="col-lg-7 p-4 p-lg-5"><h3 class="fw-bold">Choose a stakeholder persona</h3><p class="text-secondary">Every role gets the workflows it is expected to perform.</p><div class="row g-2 mt-2">${ps.map(p=>`<div class="col-md-6"><div class="persona-card" onclick="window.loginAs('${p.id}')"><div class="d-flex gap-3"><i class="bi ${p.icon} fs-4 text-success"></i><div><div class="fw-bold">${esc(p.name)}</div><div class="small text-secondary">${esc(p.desc)}</div></div></div></div></div>`).join('')}</div></div></div></div></div>`;}
window.loginAs=id=>{db.setPersona(id);sessionStorage.setItem('ussLogged','1');location.hash='#/dashboard';render();};
window.logout=()=>{sessionStorage.removeItem('ussLogged');login();};
window.switchPersona=id=>{db.setPersona(id);location.hash='#/dashboard';render();};
window.__ussShell=shell;window.toggleSidebar=()=>document.body.classList.toggle('sidebar-open');window.closeSidebar=()=>document.body.classList.remove('sidebar-open');window.openSidebar=()=>document.body.classList.add('sidebar-open');function shell(content){const p=persona(),allowed=roleRoutes[p.id]||['dashboard'];const nav=allNav.filter(n=>allowed.includes(n[1]));const _ed=(db.exportState&&db.exportState().activeEdition)||'visibility';const _out=db.exportState&&db.exportState().coverageOutage;const _sim=db.exportState&&db.exportState().simulationMode;document.body.classList.remove('sidebar-open');app.innerHTML=`<div class="app-shell"><div class="sidebar-backdrop" onclick="window.closeSidebar()" aria-hidden="true"></div><aside class="sidebar" id="appSidebar"><div class="brand"><div class="d-flex align-items-center gap-3 flex-grow-1 min-w-0"><div class="brand-mark">USS</div><div class="min-w-0"><div class="fw-bold text-white text-truncate">Behavioral Visibility</div><small>Functional Prototype v3</small></div></div><button type="button" class="btn btn-sm btn-dark sidebar-close-btn" onclick="window.closeSidebar()" aria-label="Close menu"><i class="bi bi-x-lg"></i></button></div><div class="nav-scroll"><div class="nav-section">Workspace</div>${nav.map(n=>`<a href="#/${n[1]}" class="side-link ${route()===n[1]?'active':''}" onclick="window.closeSidebar()"><i class="bi ${n[2]}"></i><span>${n[0]}</span></a>`).join('')}</div><div class="sidebar-footer"><div class="d-flex align-items-center gap-2"><div class="avatar">${p.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</div><div class="flex-grow-1 overflow-hidden"><div class="small fw-bold text-white text-truncate">${esc(p.name)}</div><div class="small text-secondary text-truncate">Demo Persona</div></div><button class="btn btn-sm btn-dark" onclick="window.logout()"><i class="bi bi-box-arrow-right"></i></button></div></div></aside><main class="main"><header class="topbar"><div class="d-flex align-items-center gap-2 topbar-left min-w-0"><button type="button" class="btn btn-soft mobile-nav-btn" onclick="window.toggleSidebar()" aria-label="Open menu"><i class="bi bi-list fs-5"></i></button><button class="btn btn-soft" onclick="window.openCommand()"><i class="bi bi-search"></i><span class="search-label ms-2">Search / Command</span><span class="ms-2 small text-secondary d-none d-md-inline">Ctrl K</span></button><span class="demo-banner d-none d-xl-inline text-truncate"><i class="bi bi-lightning-charge-fill me-1"></i>Scenario: ${esc(db.state.scenario)}</span></div><div class="d-flex gap-2 align-items-center topbar-right flex-shrink-0"><select class="form-select form-select-sm persona-select" onchange="window.switchPersona(this.value)">${db.get('personas').map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>View as: ${esc(x.name)}</option>`).join('')}</select><button class="btn btn-sm btn-outline-secondary scenarios-btn" onclick="window.showScenarios()"><i class="bi bi-play-circle"></i><span class="scenarios-label ms-1">Scenarios</span></button></div></header><div class="content"><div class="demo-banner mb-3 d-flex flex-wrap gap-2 align-items-center justify-content-between"><span><b>USS Prototype v3</b> · MRS 1.2 · Edition <span class="badge text-bg-dark">${_ed}</span>${_sim?' · <span class="badge text-bg-warning">Simulation</span>':''}${_out?' · <span class="badge text-bg-danger">Coverage outage</span>':''}</span><span class="small d-flex flex-wrap gap-2 align-items-center"><a href="#/golden">Golden Scenarios</a> · <a href="#/coverage">Coverage</a> · <a href="#/editions">Editions</a><button type="button" class="btn btn-sm btn-outline-danger ms-1" onclick="window.resetDemo()" title="Clear localStorage and reload seed">Reset Demo</button></span></div>${content}</div></main></div>`;}

function dashboard(){const p=persona();let body='';if(p.id==='employee')body=employeeDashboard();else if(p.id==='executive')body=executiveDashboard();else if(['manager','hr'].includes(p.id))body=workforceDashboard(true);else if(p.id==='it_admin')body=itDashboard();else if(p.id==='super_admin')body=platformDashboard();else if(p.id==='company_admin')body=companyAdminDashboard();else if(p.id==='risk')body=riskDashboard();else if(p.id==='dlp')body=dlpDashboard();else if(p.id==='investigator')body=investigatorDashboard();else if(p.id==='legal')body=legalDashboard();else if(p.id==='compliance')body=complianceDashboard();else if(p.id==='auditor')body=auditorDashboard();else if(p.id==='privacy')body=privacyDashboard();else body=securityDashboard();shell(head(`${p.name} Dashboard`,`Role-specific operational view for ${p.desc.toLowerCase()}.`,`<button class="btn btn-success" onclick="window.showScenarios()"><i class="bi bi-play-fill me-1"></i>Run Scenario</button>`)+body);setTimeout(drawDashboardCharts,30);}
function securityDashboard(){const a=db.get('alerts'),u=db.get('users');return `<div class="kpi-grid mb-4">${metric('Open Alerts',a.filter(x=>x.status==='Open').length,'Prioritized by severity','bi-exclamation-triangle')}${metric('High Risk Users',u.filter(x=>x.risk>=70).length,'Behavioral score ≥ 70','bi-person-exclamation')}${metric('Investigations',db.get('investigations').length,'Cases with preserved evidence','bi-search')}${metric('DLP Incidents',db.get('sensitiveIncidents').length,'Adaptive controls simulated','bi-shield-lock')}</div><div class="row g-3"><div class="col-xl-8"><div class="card-soft p-3"><div class="d-flex justify-content-between mb-3"><b>Risk & Alert Trend</b><span class="small-muted">Last 7 days</span></div><canvas id="riskChart" height="105"></canvas></div></div><div class="col-xl-4"><div class="card-soft p-3 h-100"><b>Top Risk Users</b><div class="mt-3">${[...u].sort((a,b)=>b.risk-a.risk).slice(0,5).map(x=>`<a href="#/users?id=${x.id}" class="d-flex align-items-center gap-2 py-2 text-dark"><div class="avatar">${x.avatar}</div><div class="flex-grow-1"><div class="fw-semibold">${esc(x.name)}</div><div class="small-muted">${esc(x.dept)}</div></div><b>${x.risk}</b></a>`).join('')}</div></div></div><div class="col-xl-7"><div class="card-soft p-3"><div class="d-flex justify-content-between"><b>Priority Alerts</b><a href="#/alerts" class="small">View all</a></div>${a.slice(0,4).map(alertRow).join('')}</div></div><div class="col-xl-5"><div class="card-soft p-3 h-100"><b>Behavioral Signal Mix</b><canvas id="signalChart" height="170"></canvas></div></div></div>`;}
function platformDashboard(){const t=db.get('tenants');return `<div class="kpi-grid mb-4">${metric('Organizations',t.length,'Multi-tenant SaaS simulation','bi-buildings')}${metric('Monitored Users',t.reduce((s,x)=>s+x.users,0).toLocaleString(),'Licensed identities','bi-people')}${metric('Endpoints',t.reduce((s,x)=>s+x.devices,0).toLocaleString(),'Cross-platform fleet','bi-pc-display')}${metric('Platform Health',t.filter(x=>x.health==='Healthy').length+'/'+t.length,'Tenant health','bi-heart-pulse')}</div><div class="card-soft p-3"><div class="d-flex justify-content-between"><b>Tenant Overview</b><a href="#/tenants">Manage tenants</a></div><div class="table-wrap mt-2">${tenantTable(t)}</div></div>`;}
function itDashboard(){const d=db.get('devices');return `<div class="kpi-grid mb-4">${metric('Endpoints',d.length,'Managed demo fleet','bi-pc-display')}${metric('Online',d.filter(x=>x.status==='Online').length,'Reporting now','bi-wifi')}${metric('Needs Attention',d.filter(x=>x.health!=='Healthy').length,'Update / warning / install','bi-tools')}${metric('Policies',db.get('policies').length,'Assignable configurations','bi-sliders')}</div>${deviceTable(d)}`;}
function workforceDashboard(){const w=db.get('work');return `<div class="kpi-grid mb-4">${metric('Avg Productivity',Math.round(w.reduce((s,x)=>s+x.prod,0)/w.length)+'%','Context-aware classification','bi-graph-up-arrow')}${metric('High Burnout Teams',w.filter(x=>x.burnout==='High').length,'Workload signal, not diagnosis','bi-fire')}${metric('Avg Focus', (w.reduce((s,x)=>s+x.focus,0)/w.length).toFixed(1)+'h','Focused work estimate','bi-bullseye')}${metric('Overtime Hotspots',w.filter(x=>x.overtime>=25).length,'Review workload','bi-clock-history')}</div><div class="row g-3"><div class="col-xl-8"><div class="card-soft p-3"><b>Department Productivity & Overtime</b><canvas id="workChart" height="110"></canvas></div></div><div class="col-xl-4"><div class="card-soft p-3 h-100"><b>Actionable Workforce Signals</b>${w.map(x=>`<button class="w-100 text-start btn btn-light border mt-2" onclick="window.showDepartment('${x.dept}')"><div class="d-flex justify-content-between"><b>${x.dept}</b>${badge(x.burnout,x.burnout==='High'?'risk-high':x.burnout==='Medium'?'risk-medium':'risk-low')}</div><div class="small-muted">Productivity ${x.prod}% · Focus ${x.focus}h · Overtime ${x.overtime}%</div></button>`).join('')}</div></div></div>`;}
function executiveDashboard(){const w=db.get('work'),u=db.get('users');return `<div class="kpi-grid mb-4">${metric('Organization Risk','Elevated','Finance & Operations need review','bi-shield-exclamation')}${metric('Workforce Productivity',Math.round(w.reduce((s,x)=>s+x.prod,0)/w.length)+'%','Stable overall','bi-bar-chart')}${metric('High Risk Users',u.filter(x=>x.risk>=70).length,'Human review required','bi-person-exclamation')}${metric('AI Governance Events',db.get('alerts').filter(x=>x.type==='AI Governance').length,'Public AI monitoring','bi-stars')}</div><div class="row g-3"><div class="col-xl-7"><div class="card-soft p-4"><h5 class="fw-bold">Executive Priorities</h5><div class="condition mt-3"><b>1. Reduce Finance data-movement risk</b><div class="small-muted">Risk trend and USB/cloud exfiltration require leadership follow-up.</div></div><div class="condition mt-2"><b>2. Review Operations workload</b><div class="small-muted">Overtime and burnout signals remain elevated.</div></div><div class="condition mt-2"><b>3. Govern public AI adoption</b><div class="small-muted">Sensitive prompts require policy rollout and training.</div></div></div></div><div class="col-xl-5"><div class="card-soft p-4"><h5 class="fw-bold">Strategic drill-down</h5><a href="#/risk" class="btn btn-soft w-100 mt-3">Organization Risk</a><a href="#/workforce" class="btn btn-soft w-100 mt-2">Workforce Intelligence</a><a href="#/reports" class="btn btn-soft w-100 mt-2">Board-ready Reports</a></div></div></div>`;}
function employeeDashboard(){const ack=db.get('acknowledgements')[0];return `<div class="kpi-grid mb-4">${metric('Monitoring Notice',ack?.acknowledged?'Acknowledged':'Action Required','Privacy transparency','bi-person-check')}${metric('Retention',db.get('privacy').retention,'Default policy','bi-hourglass-split')}${metric('Focused Capture',db.get('privacy').screenshot,'Governed by approval','bi-camera')}${metric('Sensitive Sites','Do Not Record','Privacy boundary','bi-eye-slash')}</div><div class="card-soft p-4"><h4 class="fw-bold">Your workplace monitoring & privacy view</h4><p class="text-secondary">See what is monitored, why, retention, privacy exclusions and your acknowledgement status.</p><a href="#/transparency" class="btn btn-success">Open Transparency Center</a></div>`;}
function companyAdminDashboard(){const u=db.get('users'),d=db.get('devices'),p=db.get('policies');return `<div class="kpi-grid mb-4">${metric('Users',u.length,'Organization identities','bi-people')}${metric('Endpoints',d.length,'Managed fleet','bi-pc-display')}${metric('Active Policies',p.filter(x=>x.status==='Active').length,'Monitoring / DLP / Privacy','bi-sliders')}${metric('Open Risk Alerts',db.get('alerts').filter(x=>x.status==='Open').length,'Requires accountable owners','bi-exclamation-triangle')}</div><div class="row g-3"><div class="col-xl-7"><div class="card-soft p-3"><b>Administration Priorities</b><a href="#/organization" class="btn btn-soft w-100 text-start mt-3">Review organization and identity sync</a><a href="#/devices" class="btn btn-soft w-100 text-start mt-2">Review agent coverage and health</a><a href="#/policies" class="btn btn-soft w-100 text-start mt-2">Review policy rollout and simulations</a><a href="#/privacy" class="btn btn-soft w-100 text-start mt-2">Review privacy boundaries and approvals</a></div></div><div class="col-xl-5"><div class="card-soft p-3"><b>Department Snapshot</b>${db.get('departments').slice(0,5).map(x=>`<div class="d-flex justify-content-between py-2 border-bottom"><span>${x.name}</span><span>Risk <b>${x.risk}</b> · Prod <b>${x.productivity}%</b></span></div>`).join('')}</div></div></div>`;}
function riskDashboard(){const u=[...db.get('users')].sort((a,b)=>b.risk-a.risk);return `<div class="kpi-grid mb-4">${metric('High Risk Users',u.filter(x=>x.risk>=70).length,'Behavioral score ≥70','bi-person-exclamation')}${metric('Focused Observation',db.get('observationRequests').length,'Governed escalation','bi-eye')}${metric('Critical Signals',db.get('alerts').filter(x=>x.score>=90).length,'Cross-signal correlation','bi-activity')}${metric('Sequence Detections','3','Ordered behavioral patterns','bi-diagram-3')}</div><div class="card-soft p-3"><div class="d-flex justify-content-between"><b>Risk-ranked Subjects</b><a href="#/risk">Open Risk Workspace</a></div>${userTable(u.slice(0,5))}</div>`;}
function dlpDashboard(){const inc=db.get('sensitiveIncidents');return `<div class="kpi-grid mb-4">${metric('Sensitive Incidents',inc.length,'Current demo period','bi-file-lock')}${metric('Blocked',inc.filter(x=>x.decision==='Blocked').length,'Prevented transfer','bi-shield-lock')}${metric('Public AI Events',inc.filter(x=>x.channel==='Public GenAI').length,'Shadow AI governance','bi-stars')}${metric('Active DLP Policies',db.get('policies').filter(x=>x.type==='DLP'&&x.status==='Active').length,'Risk-aware controls','bi-bezier2')}</div><div class="card-soft p-3"><div class="d-flex justify-content-between"><b>Priority DLP Incidents</b><a href="#/dlp">Open DLP Workspace</a></div>${simpleTable(['Incident','User','Data','Channel','Risk','Decision'],inc.map(x=>[x.id,userName(x.user),x.dataClass,x.channel,x.risk,x.decision]),true,'openDLPIncident')}</div>`;}
function investigatorDashboard(){const iv=db.get('investigations');return `<div class="kpi-grid mb-4">${metric('Open Cases',iv.filter(x=>x.status!=='Closed').length,'Assigned / team cases','bi-search')}${metric('Evidence Items',iv.reduce((s,x)=>s+(x.evidence||0),0),'Preserved context','bi-box-seam')}${metric('Case Notes',iv.reduce((s,x)=>s+(x.notes||0),0),'Analyst annotations','bi-journal-text')}${metric('High/Critical Cases',iv.filter(x=>['High','Critical'].includes(x.severity)).length,'Prioritize review','bi-exclamation-diamond')}</div><div class="card-soft p-3"><div class="d-flex justify-content-between"><b>Investigation Queue</b><a href="#/investigations">Open Case Workspace</a></div>${simpleTable(['Case','Title','Subject','Severity','Status'],iv.map(x=>[x.id,x.title,userName(x.subject),x.severity,x.status]),true,'openInvestigation')}</div>`;}
function legalDashboard(){const iv=db.get('investigations');return `<div class="kpi-grid mb-4">${metric('Cases for Review',iv.length,'Evidence-ready matters','bi-briefcase')}${metric('Evidence Exports',db.get('audits').filter(x=>String(x.action).toLowerCase().includes('export')).length,'Audited package generation','bi-download')}${metric('Chain-of-Custody Events',db.get('audits').filter(x=>String(x.purpose).toLowerCase().includes('investigation')).length,'Evidence access history','bi-link-45deg')}${metric('Redaction','Enabled','Privacy-safe legal review','bi-eye-slash')}</div><div class="row g-3"><div class="col-xl-8"><div class="card-soft p-3"><b>Cases & Evidence</b>${simpleTable(['Case','Title','Severity','Owner','Status'],iv.map(x=>[x.id,x.title,x.severity,x.owner,x.status]),true,'openInvestigation')}</div></div><div class="col-xl-4"><div class="card-soft p-3"><b>Legal Workflow</b><div class="condition mt-2">Review evidence relevance and chain of custody.</div><div class="condition mt-2">Export redacted or original manifests based on authority.</div><div class="condition mt-2">Record legal notes and final case disposition.</div></div></div></div>`;}
function complianceDashboard(){return `<div class="kpi-grid mb-4">${metric('Sensitive Incidents',db.get('sensitiveIncidents').length,'DLP / compliance scope','bi-clipboard-check')}${metric('Privacy Controls','Active','Retention + redaction + DNR','bi-eye-slash')}${metric('Audit Events',db.get('audits').length,'Administrative traceability','bi-journal-check')}${metric('Scheduled Reports',db.get('reportSchedules').filter(x=>x.enabled).length,'Recurring evidence','bi-calendar-check')}</div><div class="row g-3"><div class="col-xl-7"><div class="card-soft p-3"><b>Compliance Actions</b><a href="#/dlp" class="btn btn-soft w-100 text-start mt-3">Review sensitive-data events</a><a href="#/privacy" class="btn btn-soft w-100 text-start mt-2">Review retention, redaction and observation approvals</a><a href="#/audit" class="btn btn-soft w-100 text-start mt-2">Review administrative audit trail</a><a href="#/reports" class="btn btn-soft w-100 text-start mt-2">Generate compliance evidence report</a></div></div><div class="col-xl-5"><div class="card-soft p-3"><b>Control Health</b>${[['PII redaction','Healthy'],['Do Not Record','Healthy'],['Dual approval','Healthy'],['Evidence audit','Healthy']].map(x=>`<div class="d-flex justify-content-between py-2 border-bottom"><span>${x[0]}</span>${badge(x[1],'status-online')}</div>`).join('')}</div></div></div>`;}
function auditorDashboard(){const a=db.get('audits');return `<div class="kpi-grid mb-4">${metric('Audit Events',a.length,'Immutable-style demo ledger','bi-journal-check')}${metric('Evidence Access',a.filter(x=>String(x.action).toLowerCase().includes('evidence')).length,'Privileged review actions','bi-eye')}${metric('Policy Changes',a.filter(x=>String(x.action).toLowerCase().includes('policy')).length,'Configuration accountability','bi-sliders')}${metric('Exports',a.filter(x=>String(x.action).toLowerCase().includes('export')).length,'Report/evidence exports','bi-download')}</div><div class="card-soft p-3"><div class="d-flex justify-content-between"><b>Recent Audit Events</b><a href="#/audit">Open Audit Trail</a></div>${auditTable(a.slice(0,8))}</div>`;}
function privacyDashboard(){const p=db.get('privacy'),obs=db.get('observationRequests');return `<div class="kpi-grid mb-4">${metric('Default Retention',p.retention,'Configurable by purpose','bi-hourglass')}${metric('Focused Observation',obs.length,'Approval-governed','bi-eye')}${metric('Pending Approvals',obs.filter(x=>String(x.status).includes('Pending')).length,'Dual authorization','bi-person-check')}${metric('PII Redaction',p.piiRedaction,'Evidence privacy','bi-person-vcard')}</div><div class="row g-3"><div class="col-xl-7"><div class="card-soft p-3"><b>Privacy Boundaries</b>${[['Screenshot',p.screenshot],['Keystroke',p.keystroke],['Sensitive Sites',p.sensitiveSites],['Dual Approval',p.dualApproval]].map(x=>`<div class="d-flex justify-content-between py-3 border-bottom"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></div><div class="col-xl-5"><div class="card-soft p-3"><b>Approval Queue</b>${obs.map(o=>`<div class="condition mt-2"><div class="d-flex justify-content-between"><b>${o.id}</b>${badge(o.status,o.status==='Approved'?'status-online':'status-warning')}</div><div class="small-muted">${userName(o.user)} · Level ${o.level}</div></div>`).join('')}</div></div></div>`;}

function alertRow(x){return `<a href="#/alerts?id=${x.id}" class="d-flex gap-3 py-3 border-bottom text-dark"><div class="pt-1"><span class="severity-dot dot-${x.severity.toLowerCase()}"></span></div><div class="flex-grow-1"><div class="fw-semibold">${esc(x.title)}</div><div class="small-muted">${userName(x.user)} · ${esc(x.type)} · ${esc(x.time)}</div></div>${badge(x.severity,riskClass(x.severity))}</a>`;}

function users(){const us=db.get('users');shell(head('People & Behavioral Profiles','Search, filter and drill into activity, applications, files, risk, alerts and devices.','<button class="btn btn-success" onclick="window.importUsers()"><i class="bi bi-upload me-1"></i>Import Users</button>')+`<div class="card-soft p-3 mb-3"><div class="row g-2"><div class="col-md-5"><input id="userQ" class="form-control" placeholder="Search name, ID, department, role…" oninput="window.filterUsers()"></div><div class="col-md-3"><select id="userDept" class="form-select" onchange="window.filterUsers()"><option value="">All departments</option>${[...new Set(us.map(x=>x.dept))].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="col-md-2"><select id="userRisk" class="form-select" onchange="window.filterUsers()"><option value="">All risk</option><option value="70">High ≥70</option><option value="40">Moderate ≥40</option></select></div><div class="col-md-2"><button class="btn btn-soft w-100" onclick="window.exportUsers()">Export CSV</button></div></div></div><div id="userTableHost" class="card-soft p-3">${userTable(us)}</div>`);}
function userTable(us){return `<div class="table-wrap"><table class="table"><thead><tr><th>User</th><th>Department</th><th>Role</th><th>Risk</th><th>Productivity</th><th>Baseline</th><th>Status</th></tr></thead><tbody>${us.map(x=>`<tr onclick="location.hash='#/users?id=${x.id}'" style="cursor:pointer"><td><div class="d-flex align-items-center gap-2"><div class="avatar">${x.avatar}</div><div><b>${esc(x.name)}</b><div class="small-muted">${x.id}</div></div></div></td><td>${esc(x.dept)}</td><td>${esc(x.role)}</td><td>${badge(x.risk,x.risk>=80?'risk-critical':x.risk>=60?'risk-high':x.risk>=40?'risk-medium':'risk-low')}</td><td><div class="d-flex gap-2 align-items-center"><div class="mini-bar" style="width:80px"><span style="width:${x.productivity}%"></span></div>${x.productivity}%</div></td><td>${esc(x.baseline)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`;}
window.filterUsers=()=>{const q=(document.getElementById('userQ')?.value||'').toLowerCase(),dept=document.getElementById('userDept')?.value||'',min=Number(document.getElementById('userRisk')?.value||0);const us=db.get('users').filter(x=>(!q||[x.name,x.id,x.dept,x.role].join(' ').toLowerCase().includes(q))&&(!dept||x.dept===dept)&&(!min||x.risk>=min));document.getElementById('userTableHost').innerHTML=userTable(us);};
window.exportUsers=()=>download('users.csv',csv(db.get('users')),'text/csv');
window.importUsers=()=>showModal('Import Users',`<p class="text-secondary">Paste CSV-like rows: Name, Department, Role, Manager. This simulation creates users in localStorage.</p><textarea id="importUserText" class="form-control" rows="7">Ayesha Kabir,Finance,Finance Analyst,Karim Hasan\nShafiq Ahmed,Operations,Operations Officer,Rezaul Karim</textarea>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveImportedUsers()">Import</button>`);
window.saveImportedUsers=()=>{const lines=(document.getElementById('importUserText').value||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);const arr=lines.map(line=>{const [name,dept,role,manager]=line.split(',').map(x=>x.trim());return {name,dept,role,manager};});db.addUsers(arr);window.closeModal();toast(`${arr.length} users imported`);render();};
function userDetail(id){const u=db.user(id);if(!u)return users();const tab=params().get('tab')||'overview';const tabs=['overview','activity','apps','web','files','risk','alerts','devices'];shell(head(u.name,`${u.role} · ${u.dept} · ${u.location}`,`<button class="btn btn-outline-danger" onclick="window.requestObservation('${u.id}')"><i class="bi bi-eye me-1"></i>Request Focused Observation</button>`)+`<div class="card-soft p-2 mb-3"><div class="nav nav-pills gap-1 flex-wrap">${tabs.map(t=>`<button class="nav-link ${tab===t?'active':''}" onclick="window.userTab('${u.id}','${t}')">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div></div>${userTabContent(u,tab)}`);}
window.userTab=(id,tab)=>{location.hash=`#/users?id=${id}&tab=${tab}`;};
function userTabContent(u,tab){const id=u.id,acts=db.get('activities').filter(x=>x.user===id),dev=db.get('devices').filter(x=>x.user===id),files=db.get('fileEvents').filter(x=>x.user===id),apps=db.get('appUsage').filter(x=>x.user===id),web=db.get('webUsage').filter(x=>x.user===id),alerts=db.get('alerts').filter(x=>x.user===id);
 if(tab==='activity')return `<div class="card-soft p-3"><b>Unified Activity Timeline</b><div class="timeline mt-3">${acts.length?acts.map(a=>timelineItem(a)).join(''):'<div class="empty">No demo events for this user.</div>'}</div></div>`;
 if(tab==='apps')return `<div class="card-soft p-3">${simpleTable(['Application','Minutes','Classification','Risk'],apps.map(x=>[x.app,x.minutes,x.classification,x.risk]))}</div>`;
 if(tab==='web')return `<div class="card-soft p-3">${simpleTable(['Website','Minutes','Category','Classification','Risk'],web.map(x=>[x.site,x.minutes,x.category,x.classification,x.risk]))}</div>`;
 if(tab==='files')return `<div class="card-soft p-3">${fileTable(files)}</div>`;
 if(tab==='risk')return `<div class="row g-3"><div class="col-xl-7"><div class="card-soft p-3"><div class="d-flex justify-content-between"><b>Explainable Risk Ledger</b><span class="code-chip">ueba-v4.2</span></div>${db.get('riskFactors').map(f=>`<div class="condition mt-2 d-flex justify-content-between"><span>${f.label}</span><b>+${f.value}</b></div>`).join('')}</div></div><div class="col-xl-5"><div class="card-soft p-3"><b>Baseline Comparison</b>${[['Login time','08:45–09:15','02:13'],['Daily download','20–40 MB','1.9 GB'],['USB usage','Rare','New device'],['Location','Dhaka HQ','Dhaka HQ']].map(x=>`<div class="py-2 border-bottom"><div class="small-muted">${x[0]}</div><div class="d-flex justify-content-between"><span>${x[1]}</span><b>${x[2]}</b></div></div>`).join('')}</div></div></div>`;
 if(tab==='alerts')return `<div class="card-soft p-3">${alerts.length?alerts.map(alertRow).join(''):'<div class="empty">No alerts for this user.</div>'}</div>`;
 if(tab==='devices')return deviceTable(dev);
 return `<div class="row g-3"><div class="col-xl-4"><div class="card-soft p-4"><div class="d-flex gap-3 align-items-center"><div class="avatar avatar-lg">${u.avatar}</div><div><h4 class="mb-0">${esc(u.name)}</h4><div class="small-muted">${esc(u.email)}</div></div></div><hr>${[['Risk score',u.risk],['Productivity',u.productivity+'%'],['Baseline',u.baseline],['Status',u.status],['Manager',u.manager]].map(x=>`<div class="d-flex justify-content-between py-2"><span>${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div></div><div class="col-xl-8"><div class="card-soft p-3 mb-3"><b>Recent Behavioral Story</b><div class="timeline mt-3">${acts.slice(0,6).map(timelineItem).join('')||'<div class="empty">No events</div>'}</div></div><div class="card-soft p-3"><b>Assigned Devices</b>${dev.map(x=>`<div class="d-flex justify-content-between border-bottom py-2"><span><b>${x.id}</b><div class="small-muted">${x.os} · ${x.policy}</div></span>${badge(x.status,x.status==='Online'?'status-online':'status-offline')}</div>`).join('')||'<div class="empty">No devices</div>'}</div></div></div>`;}
window.requestObservation=userId=>showModal('Request Focused Observation',`<div class="alert alert-warning small"><b>Privacy safeguard:</b> Level 3+ requires dual approval and is time-bounded.</div><label class="form-label">Observation level</label><select id="obsLevel" class="form-select"><option value="2">Level 2 — Enriched Context</option><option value="3" selected>Level 3 — Focused Evidence</option><option value="4">Level 4 — Preventive Control</option></select><label class="form-label mt-3">Business justification</label><textarea id="obsReason" class="form-control" rows="4">Investigate material behavioral deviation and preserve evidence around a security event.</textarea>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger" onclick="window.submitObservation('${userId}')">Submit for Approval</button>`);
window.submitObservation=userId=>{const id=db.createObservationRequest(userId,document.getElementById('obsLevel').value,document.getElementById('obsReason').value);window.closeModal();toast(`Observation request ${id} created`);};

function devices(){shell(head('Endpoint Fleet','Agent deployment, health, versioning, policy assignment and diagnostics.','<button class="btn btn-success" onclick="window.deployAgent()"><i class="bi bi-cloud-arrow-down me-1"></i>Deploy Agent</button>')+deviceTable(db.get('devices')));}
function deviceTable(d){return `<div class="card-soft p-3"><div class="table-wrap"><table class="table"><thead><tr><th>Device</th><th>User</th><th>OS</th><th>Agent</th><th>Status</th><th>Last Check-in</th><th>Policy</th><th>Health</th><th></th></tr></thead><tbody>${d.map(x=>`<tr><td><b>${x.id}</b></td><td>${userName(x.user)}</td><td>${x.os}</td><td>${x.agent}</td><td>${badge(x.status,x.status==='Online'?'status-online':x.status==='Pending'?'status-warning':'status-offline')}</td><td>${x.last}</td><td>${x.policy}</td><td>${badge(x.health,x.health==='Healthy'?'status-online':'status-warning')}</td><td><div class="dropdown"><button class="btn btn-sm btn-soft dropdown-toggle" data-bs-toggle="dropdown">Actions</button><ul class="dropdown-menu"><li><button class="dropdown-item" onclick="window.updateAgent('${x.id}')">Update agent</button></li><li><button class="dropdown-item" onclick="window.assignPolicy('${x.id}')">Apply policy</button></li><li><button class="dropdown-item" onclick="window.diagnostics('${x.id}')">Diagnostics</button></li><li><hr class="dropdown-divider"></li><li><button class="dropdown-item text-danger" onclick="window.removeAgent('${x.id}')">Uninstall agent</button></li></ul></div></td></tr>`).join('')}</tbody></table></div></div>`;}
window.deployAgent=()=>showModal('Deploy Endpoint Agent',`<div class="row g-3"><div class="col-md-6"><label class="form-label">Device ID</label><input id="depDevice" class="form-control" value="LAPTOP-${120+db.get('devices').length}"></div><div class="col-md-6"><label class="form-label">Platform</label><select id="depOS" class="form-select"><option>Windows 11</option><option>macOS 15</option><option>Ubuntu 24.04</option><option>Android 15</option><option>ChromeOS</option></select></div><div class="col-md-6"><label class="form-label">Assign user</label><select id="depUser" class="form-select">${db.get('users').map(u=>`<option value="${u.id}">${u.name}</option>`).join('')}</select></div><div class="col-md-6"><label class="form-label">Policy</label><select id="depPolicy" class="form-select">${db.get('policies').map(p=>`<option>${p.name}</option>`).join('')}</select></div></div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveDeployAgent()">Queue Deployment</button>`);
window.saveDeployAgent=()=>{db.addDevice({id:document.getElementById('depDevice').value,user:document.getElementById('depUser').value,os:document.getElementById('depOS').value,policy:document.getElementById('depPolicy').value});window.closeModal();toast('Agent deployment queued');render();};
window.updateAgent=id=>{db.updateDevice(id,{agent:'2.4.2',health:'Healthy',status:'Online',last:'Just now'});toast(`${id} updated to agent 2.4.2`);render();};
window.assignPolicy=id=>showModal('Apply Recording / DLP Policy',`<label class="form-label">Policy</label><select id="assignPolicy" class="form-select">${db.get('policies').map(p=>`<option>${p.name}</option>`).join('')}</select><div class="small-muted mt-2">Policy assignment is recorded in the holistic audit log.</div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveAssignedPolicy('${id}')">Apply</button>`);
window.saveAssignedPolicy=id=>{db.updateDevice(id,{policy:document.getElementById('assignPolicy').value});window.closeModal();toast('Policy assigned');render();};
window.diagnostics=id=>showModal(`Diagnostics — ${id}`,`<div class="diagnostic-grid"><div class="condition d-flex justify-content-between"><span>Agent service</span>${badge('Running','status-online')}</div><div class="condition d-flex justify-content-between"><span>Secure channel</span>${badge('Healthy','status-online')}</div><div class="condition d-flex justify-content-between"><span>Event queue</span><b>0 pending</b></div><div class="condition d-flex justify-content-between"><span>Policy sync</span><b>22 sec ago</b></div><div class="condition d-flex justify-content-between"><span>Last telemetry</span><b>31 sec ago</b></div></div>`,`<button class="btn btn-success" data-bs-dismiss="modal">Close</button>`);
window.removeAgent=id=>{if(confirm(`Simulate uninstalling the agent from ${id}?`)){db.updateDevice(id,{status:'Offline',health:'Agent Removed',last:'Just now'});toast('Agent uninstalled (simulated)');render();}};

function activity(){const acts=db.get('activities');shell(head('Activity Explorer','Filter and inspect normalized user activity events across applications, web, files, USB, AI, login and response.')+`<div class="card-soft p-3 mb-3"><div class="row g-2"><div class="col-md-4"><input id="actQ" class="form-control" placeholder="Search activity…" oninput="window.filterActivity()"></div><div class="col-md-3"><select id="actUser" class="form-select" onchange="window.filterActivity()"><option value="">All users</option>${db.get('users').map(u=>`<option value="${u.id}">${u.name}</option>`).join('')}</select></div><div class="col-md-3"><select id="actType" class="form-select" onchange="window.filterActivity()"><option value="">All event types</option>${[...new Set(acts.map(x=>x.type))].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="col-md-2"><button class="btn btn-soft w-100" onclick="window.exportActivities()">Export</button></div></div></div><div id="activityHost" class="card-soft p-3">${activityTable(acts)}</div>`);}
function activityTable(acts){return `<div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Type</th><th>Activity</th><th>Context</th><th>Risk</th></tr></thead><tbody>${acts.map(a=>`<tr onclick='window.activityDetail(${JSON.stringify(a)})' style="cursor:pointer"><td>${a.time}</td><td>${userName(a.user)}</td><td>${a.type}</td><td><b>${esc(a.title)}</b></td><td>${esc(a.detail)}</td><td>${badge(a.risk,riskClass(a.risk))}</td></tr>`).join('')}</tbody></table></div>`;}
window.filterActivity=()=>{const q=(document.getElementById('actQ')?.value||'').toLowerCase(),u=document.getElementById('actUser')?.value||'',t=document.getElementById('actType')?.value||'';const rows=db.get('activities').filter(a=>(!q||[a.title,a.detail,a.type,userName(a.user)].join(' ').toLowerCase().includes(q))&&(!u||a.user===u)&&(!t||a.type===t));document.getElementById('activityHost').innerHTML=activityTable(rows);};
window.activityDetail=a=>showModal('Activity Event',`<div class="event-detail"><div class="d-flex justify-content-between"><b>${esc(a.title)}</b>${badge(a.risk,riskClass(a.risk))}</div><hr>${[['User',userName(a.user)],['Time',a.time],['Type',a.type],['Context',a.detail],['Event ID','EVT-'+Math.random().toString(36).slice(2,10).toUpperCase()],['Telemetry confidence','99.2%']].map(x=>`<div class="d-flex justify-content-between py-2 border-bottom"><span>${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Close</button><button class="btn btn-success" onclick="location.hash='#/users?id=${a.user}&tab=activity';window.closeModal()">Open User Timeline</button>`);
window.exportActivities=()=>download('activity-events.csv',csv(db.get('activities')),'text/csv');

function workforce(){const w=db.get('work');shell(head('Workforce Intelligence','Privacy-conscious productivity, focus, workload, overtime and workflow signals.','<button class="btn btn-soft" onclick="window.exportWorkforce()">Export Workforce Report</button>')+`<div class="row g-3"><div class="col-xl-8"><div class="card-soft p-3">${simpleTable(['Department','Productivity','Active','Idle','Focus','Overtime','Burnout signal'],w.map(x=>[x.dept,x.prod+'%',x.active+'h',x.idle+'h',x.focus+'h',x.overtime+'%',x.burnout]),true,'showDepartment')}</div></div><div class="col-xl-4"><div class="card-soft p-3"><b>Interpretation Guardrails</b><ul class="small text-secondary mt-3"><li>Idle time is not treated as non-work by itself.</li><li>Burnout is a workload signal, not a medical diagnosis.</li><li>Department-specific productivity classifications apply.</li><li>Managers see aggregated context appropriate to role.</li></ul></div></div></div>`);}
window.showDepartment=dept=>{const x=db.get('work').find(w=>w.dept===dept);if(!x)return;showModal(`${dept} — Workforce Detail`,`<div class="kpi-grid kpi-grid-modal">${metric('Productivity',x.prod+'%','Context-aware','bi-graph-up')}${metric('Focus',x.focus+'h','Daily estimate','bi-bullseye')}${metric('Overtime',x.overtime+'%','Workload trend','bi-clock')}${metric('Burnout signal',x.burnout,'Human review','bi-fire')}</div><hr><h6>Suggested management actions</h6><div class="condition mb-2">Review workload distribution and repeated after-hours work.</div><div class="condition mb-2">Identify manual processes with high context switching.</div><div class="condition">Offer training where tool usage suggests workflow friction.</div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Close</button><button class="btn btn-success" onclick="window.recordWorkforceAction('${dept}')">Record Action Plan</button>`);};
window.recordWorkforceAction=dept=>{db.audit(db.actor(),'Recorded workforce improvement action',dept,'Workforce intelligence');db.save();window.closeModal();toast('Action plan recorded in audit trail');};
window.exportWorkforce=()=>download('workforce-intelligence.csv',csv(db.get('work')),'text/csv');

function risk(){const us=[...db.get('users')].sort((a,b)=>b.risk-a.risk),obs=db.get('observationRequests');shell(head('Behavioral Risk & UEBA','Rolling baselines, explainable risk, anomaly context, observation governance and sequence detection.','<button class="btn btn-soft" onclick="window.riskMethodology()">Risk Methodology</button>')+`<div class="row g-3"><div class="col-xl-8"><div class="card-soft p-3"><b>Risk-ranked Users</b>${userTable(us)}</div></div><div class="col-xl-4"><div class="card-soft p-3"><b>Focused Observation Requests</b>${obs.map(o=>`<div class="condition mt-2"><div class="d-flex justify-content-between"><b>${userName(o.user)}</b>${badge(o.status,o.status==='Approved'?'status-online':o.status.includes('Pending')?'status-warning':'status-offline')}</div><div class="small-muted">Level ${o.level} · ${esc(o.reason)}</div>${o.status.includes('Pending')&&['privacy','soc','company_admin'].includes(db.persona())?`<div class="mt-2"><button class="btn btn-sm btn-success me-1" onclick="window.decideObs('${o.id}','Approved')">Approve</button><button class="btn btn-sm btn-outline-danger" onclick="window.decideObs('${o.id}','Denied')">Deny</button></div>`:''}</div>`).join('')}</div><div class="card-soft p-3 mt-3"><b>Ordered Risk Sequence</b><div class="sequence-flow mt-3"><span>Off-hours login</span><i class="bi bi-arrow-right"></i><span>PII export</span><i class="bi bi-arrow-right"></i><span>Archive</span><i class="bi bi-arrow-right"></i><span>USB</span></div></div></div></div>`);}
window.decideObs=(id,d)=>{db.decideObservation(id,d);toast(`Observation ${d.toLowerCase()}`);render();};
window.riskMethodology=()=>showModal('Risk Methodology',`<p>Risk is produced by deterministic policy signals, rolling behavioral baselines, sequence detection and contextual enrichment. The prototype never treats an LLM output as proof of misconduct.</p><div class="condition"><b>Explainability</b><div class="small-muted">Every score exposes contributing factors, event evidence, model/rule version and historical trend.</div></div><div class="condition mt-2"><b>Human oversight</b><div class="small-muted">High-impact actions require configured approval or policy authority.</div></div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Close</button>`);

function alerts(){const id=params().get('id');if(id)return alertDetail(id);const a=db.get('alerts');shell(head('Alert Center','Prioritized behavioral, DLP, policy, AI governance and endpoint alerts.')+`<div class="card-soft p-3 mb-3"><div class="row g-2"><div class="col-md-5"><input id="alertQ" class="form-control" placeholder="Search alerts…" oninput="window.filterAlerts()"></div><div class="col-md-3"><select id="alertSeverity" class="form-select" onchange="window.filterAlerts()"><option value="">All severities</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select></div><div class="col-md-3"><select id="alertStatus" class="form-select" onchange="window.filterAlerts()"><option value="">All statuses</option>${[...new Set(a.map(x=>x.status))].map(x=>`<option>${x}</option>`).join('')}</select></div></div></div><div id="alertHost" class="card-soft p-3">${alertTable(a)}</div>`);}
function alertTable(a){return `<div class="table-wrap"><table class="table"><thead><tr><th>Severity</th><th>Alert</th><th>User</th><th>Type</th><th>Score</th><th>Status</th><th>Time</th></tr></thead><tbody>${a.map(x=>`<tr onclick="location.hash='#/alerts?id=${x.id}'" style="cursor:pointer"><td>${badge(x.severity,riskClass(x.severity))}</td><td><b>${esc(x.title)}</b><div class="small-muted">${x.id}</div></td><td>${userName(x.user)}</td><td>${x.type}</td><td>${x.score}</td><td>${x.status}</td><td>${x.time}</td></tr>`).join('')}</tbody></table></div>`;}
window.filterAlerts=()=>{const q=(document.getElementById('alertQ')?.value||'').toLowerCase(),sev=document.getElementById('alertSeverity')?.value||'',st=document.getElementById('alertStatus')?.value||'';const a=db.get('alerts').filter(x=>(!q||[x.title,x.id,x.type,userName(x.user)].join(' ').toLowerCase().includes(q))&&(!sev||x.severity===sev)&&(!st||x.status===st));document.getElementById('alertHost').innerHTML=alertTable(a);};
function alertDetail(id){const a=db.get('alerts').find(x=>x.id===id);if(!a)return alerts();shell(head(a.title,`${a.id} · ${a.type} · ${a.time}`,`<button class="btn btn-outline-secondary" onclick="window.setAlert('${a.id}','Acknowledged')">Acknowledge</button><button class="btn btn-outline-danger" onclick="window.setAlert('${a.id}','Dismissed')">Dismiss</button><button class="btn btn-success" onclick="window.makeInvestigation('${a.id}')">Create Investigation</button>`)+`<div class="row g-3"><div class="col-xl-8"><div class="card-soft p-4 alert-strip"><div class="d-flex justify-content-between"><div><div class="small-muted">${esc(a.type)}</div><h4 class="fw-bold mt-1">${esc(a.title)}</h4></div>${badge(a.severity,riskClass(a.severity))}</div><p class="mt-3">${esc(a.details)}</p><div class="row g-2 mt-2">${[['User',userName(a.user)],['Risk score',a.score],['Status',a.status],['Detected',a.time]].map(x=>`<div class="col-md-6"><div class="condition"><div class="small-muted">${x[0]}</div><b>${esc(x[1])}</b></div></div>`).join('')}</div></div><div class="card-soft p-3 mt-3"><b>Recommended Response</b><div class="d-flex flex-wrap gap-2 mt-3"><button class="btn btn-outline-warning" onclick="window.alertResponse('${id}','Require Justification')">Require Justification</button><button class="btn btn-outline-danger" onclick="window.alertResponse('${id}','Block Transfer')">Block Transfer</button><button class="btn btn-outline-danger" onclick="window.alertResponse('${id}','Force MFA')">Force MFA</button><button class="btn btn-outline-dark" onclick="window.alertResponse('${id}','Escalate to SOC')">Escalate to SOC</button></div></div></div><div class="col-xl-4"><div class="card-soft p-3"><b>Related Context</b><a href="#/users?id=${a.user}&tab=risk" class="btn btn-soft w-100 mt-3">Open User Risk Profile</a><a href="#/activity" class="btn btn-soft w-100 mt-2">Activity Explorer</a><a href="#/dlp" class="btn btn-soft w-100 mt-2">DLP Incidents</a></div></div></div>`);}
window.setAlert=(id,status)=>{db.updateAlert(id,status);toast(`Alert ${status.toLowerCase()}`);render();};
window.makeInvestigation=alertId=>{const id=db.createInvestigationFromAlert(alertId);if(id){toast(`Investigation ${id} created`);location.hash=`#/investigations?id=${id}`;}};
window.alertResponse=(id,action)=>{db.updateAlert(id,'Investigating');db.audit(db.actor(),action,id,'Adaptive response simulation');db.save();toast(`${action} executed (simulated)`);render();};

function dlp(){const inc=db.get('sensitiveIncidents');shell(head('DLP & Sensitive Data','Classify sensitive data, inspect incidents and apply adaptive protection based on risk and destination.','<button class="btn btn-success" onclick="window.newDLPPolicy()"><i class="bi bi-plus-lg me-1"></i>New DLP Policy</button>')+`<div class="kpi-grid mb-4">${metric('PII Findings','8,430','Current demo inventory','bi-person-vcard')}${metric('PHI Findings','1,204','Protected health information','bi-heart-pulse')}${metric('Adaptive Blocks',inc.filter(x=>x.decision==='Blocked').length,'Risk-aware controls','bi-shield-lock')}${metric('Public AI Events',inc.filter(x=>x.channel==='Public GenAI').length,'Shadow AI governance','bi-stars')}</div><div class="row g-3"><div class="col-xl-8"><div class="card-soft p-3"><b>Sensitive Data Incidents</b>${simpleTable(['Incident','Time','User','Class','Channel','Volume','Risk','Decision','Status'],inc.map(x=>[x.id,x.time,userName(x.user),x.dataClass,x.channel,x.volume,x.risk,x.decision,x.status]),true,'openDLPIncident')}</div></div><div class="col-xl-4"><div class="card-soft p-3"><b>Adaptive Decision Matrix</b>${[['Customer PII → USB','Risk < 40','ALLOW'],['Customer PII → USB','Risk 40–69','WARN + JUSTIFY'],['Customer PII → USB','Risk ≥ 70','BLOCK + ALERT'],['Customer identifiers → public GenAI','Risk ≥ 40','WARN + JUSTIFY'],['Sensitive export → new cloud','Risk ≥ 70','BLOCK + INVESTIGATE']].map(x=>`<div class="condition mb-2"><div class="d-flex justify-content-between"><b>${x[0]}</b>${badge(x[2],x[2].includes('BLOCK')?'risk-critical':x[2].includes('WARN')?'risk-medium':'risk-low')}</div><div class="small-muted">${x[1]}</div></div>`).join('')}</div></div></div>`);}
window.openDLPIncident=id=>{const x=db.get('sensitiveIncidents').find(i=>i.id===id);showModal(`DLP Incident — ${id}`,`${[['User',userName(x.user)],['Data class',x.dataClass],['Channel',x.channel],['Volume',x.volume],['Risk',x.risk],['Decision',x.decision],['Policy',x.policy],['Status',x.status]].map(v=>`<div class="d-flex justify-content-between py-2 border-bottom"><span>${v[0]}</span><b>${esc(v[1])}</b></div>`).join('')}`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Close</button><button class="btn btn-success" onclick="location.hash='#/users?id=${x.user}&tab=files';window.closeModal()">Open User Context</button>`);};
window.newDLPPolicy=()=>newPolicy(true);

function policies(){const ps=db.get('policies');shell(head('Policies & Automation','No-code conditions, policy simulation, staged rollout and response automation.','<button class="btn btn-success" onclick="window.newPolicy()"><i class="bi bi-plus-lg me-1"></i>New Policy</button>')+`<div class="card-soft p-3 mb-3"><div class="table-wrap"><table class="table"><thead><tr><th>Policy</th><th>Type</th><th>Scope</th><th>Actions</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody>${ps.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="small-muted">${x.id}</div></td><td>${x.type}</td><td>${x.scope}</td><td>${x.actions}</td><td>${badge(x.status,x.status==='Active'?'status-online':'status-warning')}</td><td>${x.updated}</td><td><div class="btn-group btn-group-sm"><button class="btn btn-soft" onclick="window.simPolicy('${x.id}')">Simulate</button><button class="btn btn-soft" onclick="window.editPolicy('${x.id}')">Edit</button><button class="btn btn-soft dropdown-toggle dropdown-toggle-split" data-bs-toggle="dropdown"></button><ul class="dropdown-menu"><li><button class="dropdown-item" onclick="window.clonePolicy('${x.id}')">Clone</button></li><li><button class="dropdown-item" onclick="window.togglePolicy('${x.id}')">Toggle Active</button></li></ul></div></td></tr>`).join('')}</tbody></table></div></div><div class="card-soft p-3"><b>Visual Condition Builder Example</b><div class="d-flex flex-wrap gap-2 align-items-center mt-3"><span class="condition">Data class = Customer PII</span><b>AND</b><span class="condition">Destination = USB</span><b>AND</b><span class="condition">User risk &gt; 70</span><i class="bi bi-arrow-right"></i>${badge('BLOCK + ALERT + EVIDENCE','risk-critical')}</div></div>`);}
window.newPolicy=()=>newPolicy(false);
function newPolicy(dlpMode){showModal(dlpMode?'Create DLP Policy':'Create Policy',`<div class="row g-3"><div class="col-md-8"><label class="form-label">Policy name</label><input id="polName" class="form-control" value="${dlpMode?'Sensitive Data External Transfer':'New Behavioral Policy'}"></div><div class="col-md-4"><label class="form-label">Type</label><select id="polType" class="form-select"><option>${dlpMode?'DLP':'Behavioral Alert'}</option><option>Monitoring</option><option>Adaptive Observation</option><option>Privacy</option><option>AI Governance</option></select></div><div class="col-md-6"><label class="form-label">Scope</label><select id="polScope" class="form-select"><option>All users</option>${db.get('departments').map(d=>`<option>${d.name}</option>`).join('')}<option>Leaving employees</option></select></div><div class="col-md-6"><label class="form-label">Action</label><select id="polAction" class="form-select"><option>Alert</option><option>Warn + Justification</option><option>Block + Alert</option><option>Block + Investigate</option><option>Exclude capture</option></select></div><div class="col-12"><label class="form-label">Conditions</label><div class="condition">IF <select id="condSignal" class="form-select form-select-sm d-inline-block w-auto mx-1"><option>Data class = Customer PII</option><option>Download volume &gt; 500 MB</option><option>User risk &gt; 70</option><option>Outside office hours</option><option>Destination = Public AI</option></select> AND <select id="condDest" class="form-select form-select-sm d-inline-block w-auto mx-1"><option>Destination = USB</option><option>Destination = External Cloud</option><option>Destination = Personal Email</option><option>Destination = Public AI</option></select></div></div></div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-outline-success" onclick="window.savePolicy('Simulation')">Save & Simulate</button><button class="btn btn-success" onclick="window.savePolicy('Active')">Save Active</button>`);}
window.savePolicy=status=>{const id=db.createPolicy({name:document.getElementById('polName').value,type:document.getElementById('polType').value,scope:document.getElementById('polScope').value,actions:document.getElementById('polAction').value,status,conditions:[document.getElementById('condSignal').value,document.getElementById('condDest').value]});window.closeModal();toast(`Policy ${id} created`);render();};
window.editPolicy=id=>{const p=db.get('policies').find(x=>x.id===id);showModal(`Edit Policy — ${id}`,`<label class="form-label">Name</label><input id="editPolName" class="form-control" value="${esc(p.name)}"><label class="form-label mt-3">Scope</label><input id="editPolScope" class="form-control" value="${esc(p.scope)}"><label class="form-label mt-3">Actions</label><input id="editPolActions" class="form-control" value="${esc(p.actions)}">`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.savePolicyEdit('${id}')">Save</button>`);};
window.savePolicyEdit=id=>{db.updatePolicy(id,{name:document.getElementById('editPolName').value,scope:document.getElementById('editPolScope').value,actions:document.getElementById('editPolActions').value});window.closeModal();toast('Policy updated');render();};
window.clonePolicy=id=>{const n=db.clonePolicy(id);toast(`Policy cloned as ${n}`);render();};
window.togglePolicy=id=>{const p=db.get('policies').find(x=>x.id===id);db.updatePolicy(id,{status:p.status==='Active'?'Disabled':'Active'});toast('Policy status changed');render();};
window.simPolicy=id=>{const p=db.get('policies').find(x=>x.id===id);const seed=id.split('').reduce((a,c)=>a+c.charCodeAt(0),0);const users=20+(seed%128),events=100+(seed%410),blocks=seed%37,falsep=3+(seed%17),shots=10+(seed%61);showModal(`Policy Digital Twin — ${p.name}`,`<p class="text-secondary">Historical replay estimates impact before production rollout.</p><div class="kpi-grid kpi-grid-modal">${metric('Users affected',users,'Historical replay','bi-people')}${metric('Events matched',events,'Last 30 days','bi-lightning')}${metric('Would block',blocks,'Preventive actions','bi-shield-lock')}${metric('False-positive candidates',falsep,'Needs analyst review','bi-exclamation-circle')}</div><div class="condition mt-3"><b>Privacy exposure</b><div class="small-muted">Estimated focused screenshots: ${shots}. Review purpose limitation and exclusion rules before activation.</div></div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Close</button>${p.status!=='Active'?`<button class="btn btn-success" onclick="window.promotePolicy('${id}')">Promote to Active</button>`:''}`);};
window.promotePolicy=id=>{db.updatePolicy(id,{status:'Active'});window.closeModal();toast('Policy promoted to Active');render();};

function investigations(){const id=params().get('id');if(id)return invDetail(id);const iv=db.get('investigations');shell(head('Investigations & Digital Evidence','Case management, unified timelines, evidence preservation, session replay and chain of custody.','<button class="btn btn-success" onclick="window.newInvestigation()">New Investigation</button>')+`<div class="card-soft p-3">${simpleTable(['Case','Title','Subject','Severity','Owner','Status','Evidence'],iv.map(x=>[x.id,x.title,userName(x.subject),x.severity,x.owner,x.status,x.evidence]),true,'openInvestigation')}</div>`);}
window.openInvestigation=id=>location.hash=`#/investigations?id=${id}`;
window.newInvestigation=()=>showModal('Create Investigation',`<div class="row g-3"><div class="col-md-8"><label class="form-label">Case title</label><input id="invTitle" class="form-control" value="New security investigation"></div><div class="col-md-4"><label class="form-label">Severity</label><select id="invSeverity" class="form-select"><option>Medium</option><option>High</option><option>Critical</option><option>Low</option></select></div><div class="col-md-6"><label class="form-label">Subject</label><select id="invSubject" class="form-select">${db.get('users').map(u=>`<option value="${u.id}">${u.name} — ${u.dept}</option>`).join('')}</select></div><div class="col-md-6"><label class="form-label">Owner</label><input id="invOwner" class="form-control" value="${esc(db.actor())}"></div></div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveInvestigation()">Create Case</button>`);
window.saveInvestigation=()=>{const id=db.createInvestigation({title:document.getElementById('invTitle').value,subject:document.getElementById('invSubject').value,severity:document.getElementById('invSeverity').value,owner:document.getElementById('invOwner').value});window.closeModal();toast(`${id} created`);location.hash=`#/investigations?id=${id}`;};
function invDetail(id){const x=db.get('investigations').find(i=>i.id===id);if(!x)return investigations();const tab=params().get('tab')||'timeline';const tabs=[['timeline','Timeline'],['evidence',`Evidence (${x.evidence})`],['screenshots','Screenshots'],['files','Files'],['communications','Communications'],['audit','Audit']];shell(head(x.title,`${x.id} · ${userName(x.subject)} · Opened ${x.opened}`,`<button class="btn btn-outline-secondary" onclick="window.exportEvidence('${x.id}')"><i class="bi bi-download me-1"></i>Export Evidence</button><button class="btn btn-success" onclick="window.addCaseNote('${x.id}')"><i class="bi bi-plus-lg me-1"></i>Add Note</button>`)+`<div class="row g-3"><div class="col-xl-8"><div class="card-soft p-3 mb-3"><div class="nav nav-pills gap-1 flex-wrap">${tabs.map(t=>`<button class="nav-link ${tab===t[0]?'active':''}" onclick="window.caseTab('${x.id}','${t[0]}')">${t[1]}</button>`).join('')}</div><div class="mt-4">${caseTabContent(x,tab)}</div></div>${tab==='timeline'?sessionReconstruction(x):''}</div><div class="col-xl-4">${caseSidePanel(x)}</div></div>`);}
window.caseTab=(id,tab)=>{location.hash=`#/investigations?id=${id}&tab=${tab}`;};
function caseTabContent(x,tab){const acts=db.get('activities').filter(a=>a.user===x.subject),ev=db.get('evidence').filter(e=>e.caseId===x.id),shots=db.get('screenshots').filter(s=>s.caseId===x.id),files=db.get('fileEvents').filter(f=>f.caseId===x.id),comms=db.get('communications').filter(c=>c.caseId===x.id),aud=db.get('audits').filter(a=>a.target===x.id||a.purpose===x.id||String(a.purpose).toLowerCase().includes('investigation'));
 if(tab==='evidence')return `<div class="d-flex justify-content-between align-items-center mb-3"><b>${ev.length} evidence items</b><span class="small-muted">Select relevance to shape export package</span></div>${ev.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Relevant</th><th>Time</th><th>Type</th><th>Evidence</th><th>Source</th><th>Hash</th></tr></thead><tbody>${ev.map(e=>`<tr><td><input class="form-check-input" type="checkbox" ${e.relevant?'checked':''} onchange="window.toggleEvidence('${e.id}')"></td><td>${e.time}</td><td>${e.type}</td><td><b>${esc(e.title)}</b><div class="small-muted">${esc(e.detail)}</div></td><td>${e.source}</td><td><span class="code-chip">${e.hash}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No evidence has been attached yet.</div>'}`;
 if(tab==='screenshots')return shots.length?`<div class="screenshot-grid">${shots.map(s=>`<button class="screenshot-card" onclick="window.viewScreenshot('${s.id}')"><div class="mock-screen"><div class="mock-topbar"><span></span><span></span><span></span><b>${s.app}</b></div><div class="mock-body"><i class="bi bi-display fs-2"></i><div class="mt-2 fw-semibold">${s.title}</div></div></div><div class="p-2 text-start"><b>${s.time} · ${s.app}</b><div class="small-muted">${s.caption}</div></div></button>`).join('')}</div>`:'<div class="empty">No screenshots in this case.</div>';
 if(tab==='files')return files.length?`${fileLineage(files)}${fileTable(files)}`:'<div class="empty">No file evidence in this case.</div>';
 if(tab==='communications')return comms.length?comms.map(c=>`<div class="condition mb-2"><div class="d-flex justify-content-between"><b>${c.time} · ${c.channel}</b>${badge(c.sensitive?'Sensitive':'Normal',c.sensitive?'risk-high':'risk-low')}</div><div class="small-muted">${c.direction} · ${esc(c.counterparty)}</div><div class="mt-2"><b>${esc(c.subject)}</b></div><div>${esc(c.preview)}</div><div class="small-muted mt-2">Sentiment signal: ${c.sentiment}</div></div>`).join(''):'<div class="empty">No communication evidence in this case.</div>';
 if(tab==='audit')return `<div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Target</th><th>Purpose</th></tr></thead><tbody>${aud.map(a=>`<tr><td>${a.time}</td><td>${a.actor}</td><td>${a.action}</td><td>${a.target}</td><td>${a.purpose}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No case-specific audit entries yet.</td></tr>'}</tbody></table></div>`;
 return `<div class="timeline">${acts.length?acts.map(a=>timelineItem(a,true)).join(''):'<div class="empty">No normalized endpoint activity currently linked to this case subject.</div>'}</div>`;
}
function caseSidePanel(x){const notes=db.get('notes').filter(n=>n.caseId===x.id);return `<div class="card-soft p-3"><div class="d-flex justify-content-between"><b>Case Status</b><button class="btn btn-sm btn-soft" onclick="window.editCase('${x.id}')">Edit</button></div><div class="d-flex justify-content-between py-2 border-bottom"><span>Severity</span>${badge(x.severity,riskClass(x.severity))}</div><div class="d-flex justify-content-between py-2 border-bottom"><span>Status</span><b>${x.status}</b></div><div class="d-flex justify-content-between py-2 border-bottom"><span>Owner</span><b>${x.owner}</b></div><div class="d-flex justify-content-between py-2"><span>Evidence hash</span><span class="code-chip">sha256:8f9…c21</span></div></div><div class="card-soft p-3 mt-3"><div class="d-flex justify-content-between"><b>Case Notes</b><span>${notes.length}</span></div>${notes.slice(0,3).map(n=>`<div class="condition mt-2"><div class="d-flex justify-content-between"><b>${n.type}</b>${n.pinned?'<i class="bi bi-pin-angle-fill text-success"></i>':''}</div><div class="small-muted">${n.author} · ${n.time}</div><div class="mt-1">${esc(n.text)}</div></div>`).join('')||'<div class="small-muted mt-2">No notes yet.</div>'}</div><div class="card-soft p-3 mt-3"><b>Chain of Custody</b><div class="small-muted mt-2">Evidence access, relevance, export, redaction and review actions are immutably audited in the simulation.</div></div>`;}
function sessionReconstruction(x){const shots=db.get('screenshots').filter(s=>s.caseId===x.id);return `<div class="card-soft p-3"><div class="d-flex justify-content-between"><div><b>Session Reconstruction</b><div class="small-muted">Replay correlated screenshots and events around the incident.</div></div><button class="btn btn-sm btn-soft" ${shots.length?'':'disabled'} onclick="window.sessionReplay('${x.id}')"><i class="bi bi-play-fill"></i> Play</button></div><div class="row g-2 mt-2">${shots.slice(0,3).map(s=>`<div class="col-md-4"><button class="evidence-shot w-100" onclick="window.viewScreenshot('${s.id}')"><div class="text-center"><i class="bi bi-display fs-2"></i><div>${s.time}</div><small>${s.app}</small></div></button></div>`).join('')||'<div class="empty">No replay frames</div>'}</div></div>`;}
window.toggleEvidence=id=>{const v=db.toggleEvidenceRelevant(id);toast(v?'Marked relevant':'Removed from relevant evidence');};
window.viewScreenshot=id=>{const s=db.get('screenshots').find(x=>x.id===id);if(!s)return;showModal(`${s.time} — ${s.title}`,`<div class="mock-screen mock-screen-large"><div class="mock-topbar"><span></span><span></span><span></span><b>${s.app}</b></div><div class="mock-body"><div class="mock-window"><div class="text-secondary small">${s.sensitive?'Sensitive fields redacted in investigator preview':'Contextual evidence preview'}</div><h4 class="mt-4">${esc(s.title)}</h4><p>${esc(s.caption)}</p><div class="mock-data-lines">${Array.from({length:7},(_,i)=>`<div style="width:${92-i*6}%"></div>`).join('')}</div></div></div></div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Close</button><button class="btn btn-success" onclick="window.markScreenshotReviewed('${s.id}')">Mark Reviewed</button>`,'xl');};
window.markScreenshotReviewed=id=>{db.audit(db.actor(),'Reviewed evidence screenshot',id,'Investigation');db.save();window.closeModal();toast('Screenshot review audited');};
window.sessionReplay=caseId=>{const shots=db.get('screenshots').filter(s=>s.caseId===caseId);if(!shots.length)return;showModal('Session Replay',`<div id="replayFrame"></div><div class="d-flex align-items-center gap-2 mt-3"><button class="btn btn-soft" onclick="window.replayStep(-1)"><i class="bi bi-skip-backward"></i></button><button id="replayPlayBtn" class="btn btn-success" onclick="window.toggleReplay()"><i class="bi bi-play-fill"></i> Play</button><button class="btn btn-soft" onclick="window.replayStep(1)"><i class="bi bi-skip-forward"></i></button><input id="replaySlider" class="form-range flex-grow-1" type="range" min="0" max="${shots.length-1}" value="0" oninput="window.renderReplay(Number(this.value))"></div><div class="small-muted">Synthetic replay for UX validation; production will use endpoint evidence.</div><script type="application/json" id="replayData">${JSON.stringify(shots).replace(/</g,'\\u003c')}</script>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Close</button>`,'xl');setTimeout(()=>renderReplay(0),50);};
window.renderReplay=renderReplay;
function renderReplay(i){const el=document.getElementById('replayData');if(!el)return;const shots=JSON.parse(el.textContent),s=shots[Math.max(0,Math.min(i,shots.length-1))];document.getElementById('replaySlider').value=i;document.getElementById('replayFrame').innerHTML=`<div class="mock-screen mock-screen-large"><div class="mock-topbar"><span></span><span></span><span></span><b>${s.app} · ${s.time}</b></div><div class="mock-body"><div class="mock-window"><div class="small-muted">${s.sensitive?'Privacy redaction active':'Context frame'}</div><h3 class="mt-4">${esc(s.title)}</h3><p>${esc(s.caption)}</p><div class="mock-data-lines">${Array.from({length:8},(_,n)=>`<div style="width:${94-n*5}%"></div>`).join('')}</div></div></div></div>`;}
window.replayStep=delta=>{const slider=document.getElementById('replaySlider');if(!slider)return;const v=Math.max(Number(slider.min),Math.min(Number(slider.max),Number(slider.value)+delta));slider.value=v;renderReplay(v);};
window.toggleReplay=()=>{const btn=document.getElementById('replayPlayBtn'),slider=document.getElementById('replaySlider');if(replayTimer){clearInterval(replayTimer);replayTimer=null;btn.innerHTML='<i class="bi bi-play-fill"></i> Play';return;}btn.innerHTML='<i class="bi bi-pause-fill"></i> Pause';replayTimer=setInterval(()=>{let v=Number(slider.value)+1;if(v>Number(slider.max)){clearInterval(replayTimer);replayTimer=null;btn.innerHTML='<i class="bi bi-play-fill"></i> Play';return;}slider.value=v;renderReplay(v);},1300);};
window.addCaseNote=caseId=>showModal('Add Case Note',`<div class="row g-3"><div class="col-md-6"><label class="form-label">Type</label><select id="noteType" class="form-select"><option>Investigation Note</option><option>Evidence Note</option><option>Legal Note</option><option>Decision Note</option></select></div><div class="col-md-6"><label class="form-label">Visibility</label><select id="noteVisibility" class="form-select"><option>Investigation Team</option><option>Legal + Investigation</option><option>Security Leadership</option></select></div><div class="col-12"><label class="form-label">Note</label><textarea id="noteText" class="form-control" rows="5" placeholder="Write a factual investigation note…"></textarea></div><div class="col-12"><div class="form-check"><input id="notePinned" class="form-check-input" type="checkbox"><label class="form-check-label">Pin as important</label></div></div></div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveCaseNote('${caseId}')">Save Note</button>`);
window.saveCaseNote=caseId=>{const text=document.getElementById('noteText').value.trim();if(!text){toast('Enter a note before saving','Validation');return;}db.addNote(caseId,{type:document.getElementById('noteType').value,visibility:document.getElementById('noteVisibility').value,text,pinned:document.getElementById('notePinned').checked});window.closeModal();toast('Case note saved');render();};
window.editCase=id=>{const x=db.get('investigations').find(i=>i.id===id);showModal(`Edit Case — ${id}`,`<label class="form-label">Status</label><select id="caseStatus" class="form-select">${['Open','Under Investigation','Evidence Review','Legal Review','Contained','Closed'].map(s=>`<option ${s===x.status?'selected':''}>${s}</option>`).join('')}</select><label class="form-label mt-3">Owner</label><input id="caseOwner" class="form-control" value="${esc(x.owner)}"><label class="form-label mt-3">Severity</label><select id="caseSeverity" class="form-select">${['Low','Medium','High','Critical'].map(s=>`<option ${s===x.severity?'selected':''}>${s}</option>`).join('')}</select>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveCaseEdit('${id}')">Save</button>`);};
window.saveCaseEdit=id=>{db.updateInvestigation(id,{status:document.getElementById('caseStatus').value,owner:document.getElementById('caseOwner').value,severity:document.getElementById('caseSeverity').value});window.closeModal();toast('Case updated');render();};
window.exportEvidence=caseId=>showModal('Export Evidence Package',`<p class="text-secondary">Choose components for a redacted, auditable evidence manifest.</p>${[['expTimeline','Timeline'],['expEvidence','Evidence manifest'],['expShots','Screenshots metadata'],['expFiles','File lineage'],['expComms','Communications'],['expAudit','Audit trail']].map(x=>`<div class="form-check py-1"><input id="${x[0]}" class="form-check-input" type="checkbox" checked><label class="form-check-label" for="${x[0]}">${x[1]}</label></div>`).join('')}<hr><div class="form-check"><input id="expRedact" class="form-check-input" type="checkbox" checked><label class="form-check-label">Apply privacy redaction</label></div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.generateEvidence('${caseId}')"><i class="bi bi-download me-1"></i>Generate Package</button>`);
window.generateEvidence=caseId=>{const x=db.get('investigations').find(i=>i.id===caseId),opts={timeline:document.getElementById('expTimeline').checked,evidence:document.getElementById('expEvidence').checked,screenshots:document.getElementById('expShots').checked,files:document.getElementById('expFiles').checked,communications:document.getElementById('expComms').checked,audit:document.getElementById('expAudit').checked,redacted:document.getElementById('expRedact').checked};const pkg={case:x,exportedAt:new Date().toISOString(),exportedBy:db.actor(),options:opts};if(opts.timeline)pkg.timeline=db.get('activities').filter(a=>a.user===x.subject);if(opts.evidence)pkg.evidence=db.get('evidence').filter(e=>e.caseId===caseId&&e.relevant);if(opts.screenshots)pkg.screenshots=db.get('screenshots').filter(s=>s.caseId===caseId).map(s=>opts.redacted?Object.assign({},s,{caption:s.sensitive?'[REDACTED SENSITIVE SCREEN CONTENT]':s.caption}):s);if(opts.files)pkg.files=db.get('fileEvents').filter(f=>f.caseId===caseId);if(opts.communications)pkg.communications=db.get('communications').filter(c=>c.caseId===caseId).map(c=>opts.redacted&&c.sensitive?Object.assign({},c,{preview:'[REDACTED]'}):c);if(opts.audit)pkg.audit=db.get('audits').filter(a=>a.target===caseId||String(a.purpose).includes('Investigation'));db.audit(db.actor(),'Exported evidence package',caseId,opts.redacted?'Redacted':'Original');db.save();download(`${caseId}_evidence_manifest.json`,JSON.stringify(pkg,null,2));window.closeModal();toast('Evidence manifest downloaded and export audited');render();};

function reports(){shell(head('Reports & Universal Search','Search across entities, preview reports, export datasets and schedule recurring delivery.','<button class="btn btn-success" onclick="window.scheduleReport()">Schedule Report</button>')+`<div class="card-soft p-4 mb-3"><div class="input-group input-group-lg"><span class="input-group-text"><i class="bi bi-search"></i></span><input id="globalQ" class="form-control" placeholder="Search user, device, alert, investigation, file or keyword…"><button class="btn btn-success" onclick="window.globalSearch()">Search</button></div><div id="globalResults" class="mt-3"></div></div><div class="module-grid">${[['User Activity Report','Applications, web, files and sessions','activity'],['Insider Risk Report','Scores, factors and trends','risk'],['Sensitive Data Report','PII/PHI movement and controls','dlp'],['Workforce Report','Productivity, focus and workload','workforce'],['Agent Health Report','Coverage, versions and errors','agents'],['Audit & Compliance','Admin actions and evidence access','audit']].map(x=>`<div class="card-soft p-3"><i class="bi bi-file-earmark-bar-graph fs-3 text-success"></i><h6 class="fw-bold mt-3">${x[0]}</h6><div class="small-muted">${x[1]}</div><div class="d-flex gap-2 mt-3"><button class="btn btn-sm btn-soft" onclick="window.previewReport('${x[2]}')">Preview</button><button class="btn btn-sm btn-outline-secondary" onclick="window.downloadReport('${x[2]}')">Download CSV</button></div></div>`).join('')}</div><div class="card-soft p-3 mt-3"><b>Scheduled Reports</b>${db.get('reportSchedules').map(r=>`<div class="d-flex justify-content-between py-3 border-bottom"><div><b>${r.name}</b><div class="small-muted">${r.frequency} · ${r.recipients} · ${r.format}</div></div>${badge(r.enabled?'Enabled':'Disabled',r.enabled?'status-online':'status-offline')}</div>`).join('')}</div>`);}
window.globalSearch=()=>{const q=(document.getElementById('globalQ').value||'').trim().toLowerCase();if(!q){document.getElementById('globalResults').innerHTML='<div class="small-muted">Enter a search phrase.</div>';return;}const users=db.get('users').filter(x=>JSON.stringify(x).toLowerCase().includes(q)).slice(0,5),dev=db.get('devices').filter(x=>JSON.stringify(x).toLowerCase().includes(q)).slice(0,5),alerts=db.get('alerts').filter(x=>JSON.stringify(x).toLowerCase().includes(q)).slice(0,5),inv=db.get('investigations').filter(x=>JSON.stringify(x).toLowerCase().includes(q)).slice(0,5),files=db.get('fileEvents').filter(x=>JSON.stringify(x).toLowerCase().includes(q)).slice(0,5);const section=(title,rows,fn)=>rows.length?`<h6 class="mt-3">${title}</h6>${rows.map(r=>`<button class="btn btn-light border w-100 text-start mb-1" onclick="${fn(r)}">${esc(r.name||r.title||r.id)} <span class="small-muted">${esc(r.id||'')}</span></button>`).join('')}`:'';document.getElementById('globalResults').innerHTML=section('People',users,r=>`location.hash='#/users?id=${r.id}'`)+section('Devices',dev,r=>`location.hash='#/devices'`)+section('Alerts',alerts,r=>`location.hash='#/alerts?id=${r.id}'`)+section('Investigations',inv,r=>`location.hash='#/investigations?id=${r.id}'`)+section('Files',files,r=>`location.hash='#/users?id=${r.user}&tab=files'`)||'<div class="empty">No results.</div>';};
function reportData(kind){if(kind==='activity')return db.get('activities');if(kind==='risk')return db.get('users').map(x=>({id:x.id,name:x.name,department:x.dept,risk:x.risk,baseline:x.baseline}));if(kind==='dlp')return db.get('sensitiveIncidents');if(kind==='workforce')return db.get('work');if(kind==='agents')return db.get('devices');return db.get('audits');}
window.previewReport=kind=>{const rows=reportData(kind);showModal('Report Preview',`<div class="small-muted mb-2">Showing up to 12 rows from the current fake backend.</div>${objectTable(rows.slice(0,12))}`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Close</button><button class="btn btn-success" onclick="window.downloadReport('${kind}')">Download CSV</button>`,'xl');};
window.downloadReport=kind=>download(`${kind}-report.csv`,csv(reportData(kind)),'text/csv');
window.scheduleReport=()=>showModal('Schedule Report',`<label class="form-label">Report name</label><input id="schedName" class="form-control" value="Weekly Security Summary"><div class="row g-3 mt-1"><div class="col-md-6"><label class="form-label">Frequency</label><select id="schedFreq" class="form-select"><option>Daily · 08:00</option><option selected>Weekly · Monday 08:00</option><option>Monthly · 1st 09:00</option></select></div><div class="col-md-6"><label class="form-label">Format</label><select id="schedFormat" class="form-select"><option>PDF + CSV</option><option>PDF</option><option>CSV</option></select></div></div><label class="form-label mt-3">Recipients</label><input id="schedRecipients" class="form-control" value="Security Leadership">`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveSchedule()">Create Schedule</button>`);
window.saveSchedule=()=>{db.addReportSchedule({name:document.getElementById('schedName').value,frequency:document.getElementById('schedFreq').value,format:document.getElementById('schedFormat').value,recipients:document.getElementById('schedRecipients').value});window.closeModal();toast('Report schedule created');render();};

function ai(){shell(head('AI Investigation Copilot','Natural-language investigation over the simulated evidence model with evidence-linked answers and human oversight.')+`<div class="row g-3"><div class="col-xl-8"><div class="card-soft p-4"><label class="form-label fw-bold">Ask the platform</label><textarea id="aiQ" class="form-control" rows="4" placeholder="Example: Who accessed sensitive customer data after office hours and moved it externally?">Who accessed sensitive customer data after office hours and moved it externally?</textarea><div class="d-flex gap-2 mt-3"><button class="btn btn-success" onclick="window.askAI()"><i class="bi bi-stars me-1"></i>Analyze</button><button class="btn btn-soft" onclick="document.getElementById('aiQ').value='Which departing employees show cumulative exfiltration risk?'">Departing Employee Example</button></div><div id="aiAnswer" class="mt-4"></div></div></div><div class="col-xl-4"><div class="card-soft p-3"><b>AI Guardrails</b><ul class="small text-secondary mt-3"><li>Answers are derived from structured demo evidence.</li><li>Results link back to people, alerts and cases.</li><li>AI does not label a person guilty or malicious.</li><li>Human analyst decides consequential actions.</li><li>Production architecture may use BYO LLM / MCP.</li></ul></div></div></div>`);}
window.askAI=()=>{const q=document.getElementById('aiQ').value.toLowerCase();let users=[];if(q.includes('departing'))users=db.get('users').filter(u=>u.status.toLowerCase().includes('leaving')||u.id==='USR-0088');else if(q.includes('ai')||q.includes('genai'))users=db.get('users').filter(u=>u.id==='USR-0071');else users=db.get('users').filter(u=>u.risk>=60).slice(0,3);const cards=users.map(u=>{const a=db.get('alerts').find(x=>x.user===u.id),iv=db.get('investigations').find(x=>x.subject===u.id);return `<div class="condition mb-2"><div class="d-flex justify-content-between"><b>${u.name}</b>${badge('Risk '+u.risk,u.risk>=80?'risk-critical':'risk-high')}</div><div class="small-muted">${esc(u.baseline)} · ${esc(u.status)}</div><div class="mt-2">${a?esc(a.title):'Behavioral risk context matched the query.'}</div><div class="mt-2"><a href="#/users?id=${u.id}&tab=risk" class="me-3">User profile</a>${a?`<a href="#/alerts?id=${a.id}" class="me-3">Alert ${a.id}</a>`:''}${iv?`<a href="#/investigations?id=${iv.id}">Case ${iv.id}</a>`:''}</div></div>`;}).join('');document.getElementById('aiAnswer').innerHTML=`<div class="alert alert-info"><b>Copilot interpretation:</b> ${users.length} subject(s) matched the evidence-oriented query. These are risk indicators requiring human review, not conclusions of misconduct.</div>${cards||'<div class="empty">No matching evidence found.</div>'}`;db.audit(db.actor(),'Ran AI investigation query','Copilot',document.getElementById('aiQ').value.slice(0,80));db.save();};

function privacy(){const p=db.get('privacy'),obs=db.get('observationRequests');shell(head('Privacy & Governance','Purpose limitation, retention, redaction, Do Not Record, observation approvals and employee transparency.','<button class="btn btn-soft" onclick="window.exportPrivacy()">Export Privacy Configuration</button>')+`<div class="row g-3"><div class="col-xl-7"><div class="card-soft p-3"><b>Monitoring Boundaries</b>${privacyControl('screenshot','Screenshot capture',p.screenshot,['Focused only','Disabled','Always on (not recommended)'])}${privacyControl('keystroke','Keystroke capture',p.keystroke,['Focused only','Disabled'])}${privacyControl('sensitiveSites','Sensitive websites',p.sensitiveSites,['Do Not Record','Metadata only'])}${privacyControl('retention','Default retention',p.retention,['30 days','60 days','90 days','180 days'])}${privacyControl('piiRedaction','PII/PHI redaction',p.piiRedaction,['Enabled','Disabled'])}${privacyControl('dualApproval','Dual approval for Level 3+',p.dualApproval,['Required for Level 3+','Optional'])}</div><div class="card-soft p-3 mt-3"><div class="d-flex justify-content-between"><b>Do Not Record Domains</b><button class="btn btn-sm btn-soft" onclick="window.addDNR()">Add Domain</button></div><div id="dnrDomains" class="mt-2">${(p.dnrDomains||['banking.example','payments.example','personal-health.example']).map(d=>`<span class="badge text-bg-light border me-1 mb-1">${esc(d)}</span>`).join('')}</div></div></div><div class="col-xl-5"><div class="card-soft p-3"><b>Focused Observation Governance</b>${obs.map(o=>`<div class="condition mt-2"><div class="d-flex justify-content-between"><b>${userName(o.user)}</b>${badge(o.status,o.status==='Approved'?'status-online':o.status.includes('Pending')?'status-warning':'status-offline')}</div><div class="small-muted">${o.id} · Level ${o.level} · Requested by ${o.requestedBy}</div><div class="mt-1">${esc(o.reason)}</div>${o.status.includes('Pending')?`<div class="mt-2"><button class="btn btn-sm btn-success" onclick="window.decideObs('${o.id}','Approved')">Approve</button> <button class="btn btn-sm btn-outline-danger" onclick="window.decideObs('${o.id}','Denied')">Deny</button></div>`:''}</div>`).join('')}</div></div></div>`);}
function privacyControl(key,label,val,options){return `<div class="d-flex justify-content-between align-items-center py-3 border-bottom"><div><b>${label}</b><div class="small-muted">Audited configuration</div></div><select class="form-select form-select-sm" style="width:220px" onchange="window.changePrivacy('${key}',this.value)">${options.map(o=>`<option ${String(o)===String(val)?'selected':''}>${o}</option>`).join('')}</select></div>`;}
window.changePrivacy=(k,v)=>{db.updatePrivacy(k,v);toast(`${k} updated`);};
window.addDNR=()=>showModal('Add Do Not Record Domain',`<label class="form-label">Domain / pattern</label><input id="dnrInput" class="form-control" placeholder="example.com"><div class="small-muted mt-2">Production should support URL patterns, app scopes, field exclusions and legal purpose metadata.</div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveDNR()">Add</button>`);
window.saveDNR=()=>{const d=document.getElementById('dnrInput').value.trim();if(!d)return;const p=db.get('privacy'),arr=p.dnrDomains||['banking.example','payments.example','personal-health.example'];arr.push(d);db.updatePrivacy('dnrDomains',arr);window.closeModal();toast('Do Not Record domain added');render();};
window.exportPrivacy=()=>download('privacy-governance.json',JSON.stringify({privacy:db.get('privacy'),observationRequests:db.get('observationRequests')},null,2));

function audit(){const a=db.get('audits');shell(head('Holistic Audit Trail','Immutable-style visibility into administrator actions, evidence access, exports, policy changes and automated response.','<button class="btn btn-soft" onclick="window.exportAudit()">Export CSV</button>')+`<div class="card-soft p-3 mb-3"><input id="auditQ" class="form-control" placeholder="Filter actor, action, target or purpose…" oninput="window.filterAudit()"></div><div id="auditHost" class="card-soft p-3">${auditTable(a)}</div>`);}
function auditTable(a){return `<div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Target</th><th>Purpose</th><th>Source</th></tr></thead><tbody>${a.map(x=>`<tr><td>${x.time}</td><td><b>${x.actor}</b></td><td>${esc(x.action)}</td><td>${esc(x.target)}</td><td>${esc(x.purpose)}</td><td>${esc(x.ip)}</td></tr>`).join('')}</tbody></table></div>`;}
window.filterAudit=()=>{const q=(document.getElementById('auditQ').value||'').toLowerCase();document.getElementById('auditHost').innerHTML=auditTable(db.get('audits').filter(x=>JSON.stringify(x).toLowerCase().includes(q)));};
window.exportAudit=()=>download('audit-trail.csv',csv(db.get('audits')),'text/csv');

function integrations(){const it=db.get('integrations');shell(head('Enterprise Integrations','Microsoft 365, SIEM, IAM, communication, API, webhooks, MCP and private LLM integration.','<button class="btn btn-success" onclick="window.addIntegration()">Add Integration</button>')+`<div class="module-grid">${it.map(x=>`<div class="card-soft p-3"><div class="d-flex justify-content-between"><div class="avatar"><i class="bi bi-plug"></i></div>${badge(x.status,x.status==='Connected'||x.status==='Configured'?'status-online':'status-warning')}</div><h5 class="fw-bold mt-3">${x.name}</h5><div class="small-muted">${x.kind}</div><p class="mt-2 mb-3">${x.detail}</p><button class="btn btn-sm btn-soft" onclick="window.configureIntegration('${x.name.replace(/'/g,"\\'")}')">Configure</button></div>`).join('')}</div>`);}
window.addIntegration=()=>showModal('Add Integration',`<div class="row g-3"><div class="col-md-6"><label class="form-label">Name</label><input id="intName" class="form-control" value="Custom SIEM"></div><div class="col-md-6"><label class="form-label">Kind</label><select id="intKind" class="form-select"><option>SIEM</option><option>IAM</option><option>Cloud</option><option>Communication</option><option>AI</option><option>Custom</option></select></div><div class="col-12"><label class="form-label">Description</label><input id="intDetail" class="form-control" value="Webhook/API integration"></div></div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveIntegration()">Add</button>`);
window.saveIntegration=()=>{db.addIntegration({name:document.getElementById('intName').value,kind:document.getElementById('intKind').value,detail:document.getElementById('intDetail').value});window.closeModal();toast('Integration added');render();};
window.configureIntegration=name=>{const x=db.get('integrations').find(i=>i.name===name);showModal(`Configure — ${name}`,`<label class="form-label">Status</label><select id="intStatus" class="form-select"><option ${x.status==='Connected'?'selected':''}>Connected</option><option ${x.status==='Configured'?'selected':''}>Configured</option><option ${x.status==='Available'?'selected':''}>Available</option><option>Disconnected</option></select><label class="form-label mt-3">Endpoint / workspace</label><input id="intEndpoint" class="form-control" value="https://integration.demo.local"><div class="condition mt-3"><b>Connection test</b><div class="small-muted">Authentication ✓ · Schema compatibility ✓ · Last test 120 ms</div></div>`,`<button class="btn btn-outline-secondary" onclick="window.testIntegration('${name.replace(/'/g,"\\'")}')">Test</button><button class="btn btn-success" onclick="window.saveIntegrationConfig('${name.replace(/'/g,"\\'")}')">Save</button>`);};
window.testIntegration=name=>toast(`${name} connection test succeeded in 120 ms`);
window.saveIntegrationConfig=name=>{db.updateIntegration(name,{status:document.getElementById('intStatus').value});window.closeModal();toast('Integration configuration saved');render();};

function tenants(){const t=db.get('tenants');shell(head('SaaS Tenant Management','Provision organizations, plans, entitlements, storage, region and platform health.','<button class="btn btn-success" onclick="window.newTenant()">New Tenant</button>')+`<div class="card-soft p-3"><div class="table-wrap">${tenantTable(t)}</div></div>`);}
function tenantTable(t){return `<table class="table"><thead><tr><th>Organization</th><th>Users</th><th>Devices</th><th>Plan</th><th>Storage</th><th>Health</th><th></th></tr></thead><tbody>${t.map(x=>`<tr><td><b>${x.name}</b></td><td>${x.users}</td><td>${x.devices}</td><td>${x.plan}</td><td>${x.storage}</td><td>${badge(x.health,x.health==='Healthy'?'status-online':'status-warning')}</td><td><button class="btn btn-sm btn-soft" onclick="window.manageTenant('${x.name.replace(/'/g,"\\'")}')">Manage</button></td></tr>`).join('')}</tbody></table>`;}
window.newTenant=()=>showModal('Provision New Tenant',`<div class="row g-3"><div class="col-md-8"><label class="form-label">Organization</label><input id="tenantName" class="form-control" value="New Enterprise Customer"></div><div class="col-md-4"><label class="form-label">Plan</label><select id="tenantPlan" class="form-select"><option>Enterprise IRM + DLP</option><option>UAM + IRM</option><option>UAM + Compliance</option></select></div><div class="col-md-6"><label class="form-label">Region</label><select id="tenantRegion" class="form-select"><option>APAC</option><option>EU</option><option>US</option><option>On-Premises</option></select></div><div class="col-md-6"><label class="form-label">Licensed users</label><input id="tenantUsers" type="number" class="form-control" value="500"></div></div>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveTenant()">Provision</button>`);
window.saveTenant=()=>{db.createTenant({name:document.getElementById('tenantName').value,plan:document.getElementById('tenantPlan').value,region:document.getElementById('tenantRegion').value,users:Number(document.getElementById('tenantUsers').value)});window.closeModal();toast('Tenant provisioned');render();};
window.manageTenant=name=>{const x=db.get('tenants').find(t=>t.name===name);showModal(`Manage Tenant — ${name}`,`<label class="form-label">Plan</label><input id="mtPlan" class="form-control" value="${esc(x.plan)}"><label class="form-label mt-3">Health</label><select id="mtHealth" class="form-select"><option ${x.health==='Healthy'?'selected':''}>Healthy</option><option ${x.health==='Warning'?'selected':''}>Warning</option><option>Suspended</option></select><label class="form-label mt-3">Storage</label><input id="mtStorage" class="form-control" value="${esc(x.storage)}">`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveTenantEdit('${name.replace(/'/g,"\\'")}')">Save</button>`);};
window.saveTenantEdit=name=>{db.updateTenant(name,{plan:document.getElementById('mtPlan').value,health:document.getElementById('mtHealth').value,storage:document.getElementById('mtStorage').value});window.closeModal();toast('Tenant updated');render();};

function organization(){const d=db.get('departments'),g=db.get('groups');shell(head('Organization & Identity','Departments, teams, managers, dynamic groups and identity synchronization.','<button class="btn btn-success" onclick="window.newDepartment()">New Department</button><button class="btn btn-soft" onclick="window.importUsers()">Import Users</button>')+`<div class="row g-3"><div class="col-xl-7"><div class="card-soft p-3"><b>Departments</b>${simpleTable(['Department','Head','Users','Risk','Productivity'],d.map(x=>[x.name,x.head,x.users,x.risk,x.productivity+'%']),true,'showOrgDepartment')}</div></div><div class="col-xl-5"><div class="card-soft p-3"><b>Dynamic / Static Groups</b>${g.map(x=>`<div class="condition mt-2"><div class="d-flex justify-content-between"><b>${x.name}</b>${badge(x.type,x.type==='Dynamic'?'status-online':'status-warning')}</div><div class="small-muted">${x.members} members · ${x.rule}</div><div class="small-muted">Policy: ${x.policy}</div></div>`).join('')}</div><div class="card-soft p-3 mt-3"><b>Identity Sources</b>${[['Microsoft Entra ID','Connected'],['Active Directory','Connected'],['SCIM Provisioning','Enabled'],['CSV / Manual Import','Available']].map(x=>`<div class="d-flex justify-content-between py-3 border-bottom"><span>${x[0]}</span>${badge(x[1],'status-online')}</div>`).join('')}</div></div></div>`);}
window.newDepartment=()=>showModal('Create Department',`<label class="form-label">Name</label><input id="deptName" class="form-control" value="Risk & Compliance"><label class="form-label mt-3">Head</label><input id="deptHead" class="form-control" value="Unassigned"><label class="form-label mt-3">Parent</label><select id="deptParent" class="form-select"><option>Head Office</option><option>Branches</option></select>`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success" onclick="window.saveDepartment()">Create</button>`);
window.saveDepartment=()=>{db.createDepartment({name:document.getElementById('deptName').value,head:document.getElementById('deptHead').value,parent:document.getElementById('deptParent').value});window.closeModal();toast('Department created');render();};
window.showOrgDepartment=name=>{const x=db.get('departments').find(d=>d.name===name);showModal(name,`${[['Head',x.head],['Users',x.users],['Risk',x.risk],['Productivity',x.productivity+'%'],['Parent',x.parent]].map(v=>`<div class="d-flex justify-content-between py-2 border-bottom"><span>${v[0]}</span><b>${esc(v[1])}</b></div>`).join('')}`,`<button class="btn btn-secondary" data-bs-dismiss="modal">Close</button>`);};

function transparency(){const ack=db.get('acknowledgements')[0],p=db.get('privacy');shell(head('Employee Transparency Center','Clear, policy-driven explanation of monitoring scope, purpose and privacy boundaries.')+`<div class="row g-3"><div class="col-xl-8"><div class="card-soft p-4"><h4 class="fw-bold">What is monitored?</h4><p class="text-secondary">Only approved work-related activity within the organization’s lawful monitoring policy.</p>${[['Application and website metadata','Enabled during work context'],['Focused screenshots','Only for policy/risk conditions with authorization'],['Keystrokes',p.keystroke],['Files and external transfers','Security and data protection purpose'],['Company-owned mobile location',p.location],['Sensitive/private websites',p.sensitiveSites]].map(x=>`<div class="condition mb-2 d-flex justify-content-between"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></div><div class="col-xl-4"><div class="card-soft p-4"><b>Your protections</b><ul class="mt-3 text-secondary"><li>Purpose-limited access</li><li>Role-based visibility</li><li>PII/PHI redaction</li><li>${p.retention} default retention</li><li>Audit of evidence viewers</li><li>Human review of AI/risk signals</li></ul><div class="mb-2">${badge(ack?.acknowledged?'Acknowledged':'Not acknowledged',ack?.acknowledged?'status-online':'status-warning')}</div><button class="btn btn-outline-success w-100" ${ack?.acknowledged?'disabled':''} onclick="window.ackPolicy()">Acknowledge Policy</button><button class="btn btn-soft w-100 mt-2" onclick="window.downloadMyData()">Download My Demo Data</button></div></div></div>`);}
window.ackPolicy=()=>{db.acknowledgePolicy('USR-0042');toast('Policy acknowledgement recorded');render();};
window.downloadMyData=()=>{const id='USR-0042';download('my-monitoring-data.json',JSON.stringify({user:db.user(id),activities:db.get('activities').filter(x=>x.user===id),devices:db.get('devices').filter(x=>x.user===id),privacy:db.get('privacy')},null,2));db.audit(db.actor(),'Downloaded employee transparency data',id,'Data access request');db.save();toast('Personal demo data downloaded');};

function settings(){if(db.persona()==='employee')return employeeSettings();const s=db.get('settings');shell(head('Platform Settings','Authentication, retention, notifications, data residency and prototype state.','<button class="btn btn-success" onclick="window.saveSettings()">Save Settings</button>')+`<div class="row g-3"><div class="col-xl-7"><div class="card-soft p-3"><b>Enterprise Configuration</b><div class="row g-3 mt-1"><div class="col-md-6"><label class="form-label">MFA</label><select id="setMfa" class="form-select"><option ${s.mfa==='Required'?'selected':''}>Required</option><option>Optional</option></select></div><div class="col-md-6"><label class="form-label">Region</label><input id="setRegion" class="form-control" value="${esc(s.region)}"></div><div class="col-md-6"><label class="form-label">Default retention (days)</label><input id="setRetention" type="number" class="form-control" value="${s.retention}"></div><div class="col-md-6"><label class="form-label">Notifications</label><select id="setNotify" class="form-select"><option ${s.notifications==='Critical + High'?'selected':''}>Critical + High</option><option>Critical only</option><option>All alerts</option></select></div><div class="col-md-6"><label class="form-label">Timezone</label><input id="setTimezone" class="form-control" value="${esc(s.timezone)}"></div><div class="col-md-6"><label class="form-label">Data residency</label><input id="setResidency" class="form-control" value="${esc(s.dataResidency)}"></div></div></div></div><div class="col-xl-5"><div class="card-soft p-3"><b>Prototype Controls</b><p class="small-muted mt-2">Export/import the complete fake backend state, or reset to the original demo seed.</p><button class="btn btn-soft w-100" onclick="window.exportState()">Export Demo State</button><label class="btn btn-soft w-100 mt-2 mb-0">Import Demo State<input id="stateFile" type="file" accept="application/json" hidden onchange="window.importState(this.files[0])"></label><button class="btn btn-outline-danger w-100 mt-2" onclick="window.resetDemo()">Reset Demo Data</button></div></div></div>`);}
window.saveSettings=()=>{[['mfa','setMfa'],['region','setRegion'],['retention','setRetention'],['notifications','setNotify'],['timezone','setTimezone'],['dataResidency','setResidency']].forEach(([k,id])=>db.updateSetting(k,document.getElementById(id).value));toast('Platform settings saved');render();};
function employeeSettings(){shell(head('Personal Preferences','Employee-facing prototype preferences; enterprise monitoring controls remain read-only and governed by policy.')+`<div class="row g-3"><div class="col-xl-7"><div class="card-soft p-4"><h5 class="fw-bold">Notification Preferences</h5><div class="form-check form-switch mt-3"><input class="form-check-input" type="checkbox" id="empPolicyNotify" checked><label class="form-check-label">Notify me when workplace monitoring policy changes</label></div><div class="form-check form-switch mt-3"><input class="form-check-input" type="checkbox" id="empAckNotify" checked><label class="form-check-label">Remind me if acknowledgement is required</label></div><button class="btn btn-success mt-4" onclick="window.saveEmployeePrefs()">Save Preferences</button></div></div><div class="col-xl-5"><div class="card-soft p-4"><b>Privacy Controls</b><p class="small-muted mt-2">Monitoring scope, retention, redaction and Do Not Record rules are managed by authorized privacy/security roles and are visible in the Transparency Center.</p><a href="#/transparency" class="btn btn-soft w-100">Open Transparency Center</a></div></div></div>`);}
window.saveEmployeePrefs=()=>{db.audit(db.actor(),'Updated personal notification preferences','USR-0042','Employee settings');db.save();toast('Personal preferences saved');};
window.exportState=()=>download('uss-prototype-state.json',JSON.stringify(db.exportState(),null,2));
window.importState=file=>{if(!file)return;const r=new FileReader();r.onload=()=>{try{db.importState(JSON.parse(r.result));toast('Demo state imported');render();}catch(e){toast('Invalid state file','Import Error');}};r.readAsText(file);};
window.resetDemo=()=>{if(confirm('Reset all demo data to the v3 seed? This clears local saved state.')){try{localStorage.removeItem('uss_bv_prototype_state_v3');localStorage.removeItem('uss_bv_prototype_state_v2');}catch(e){}db.reset();toast('Demo reset to v3 seed');location.hash='#/dashboard';render();}};

window.showScenarios=()=>showModal('Demo Scenario Engine',`<p class="text-secondary">Choose a story. The fake backend updates risk, alerts, workforce signals and audit state.</p>${db.get('scenarios').map(x=>`<button class="scenario-btn" onclick="window.runScenario('${x.id}')"><b>${x.name}</b><div class="small-muted">${x.desc}</div></button>`).join('')}`);
window.runScenario=id=>{db.simulateScenario(id);window.closeModal();toast(`Scenario activated: ${id}`);render();};
window.openCommand=()=>{document.getElementById('cmd')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="command-overlay" id="cmd"><div class="command-box"><div class="p-3"><input id="cmdInput" autofocus class="form-control form-control-lg border-0" placeholder="Search workspaces, people, alerts and cases…" oninput="window.cmdFilter()"></div><div class="command-results" id="cmdResults"></div><div class="p-2 small-muted border-top">Esc to close · Ctrl/Cmd K to open</div></div></div>`);cmdFilter();document.getElementById('cmdInput').focus();};
window.cmdFilter=()=>{const q=(document.getElementById('cmdInput')?.value||'').toLowerCase(),allowed=roleRoutes[db.persona()]||[];let items=[];allNav.filter(n=>allowed.includes(n[1])&&n[0].toLowerCase().includes(q)).forEach(n=>items.push({icon:n[2],label:n[0],sub:'Workspace',go:`#/${n[1]}`}));if(q.length>=1){db.get('users').filter(u=>[u.name,u.id,u.dept].join(' ').toLowerCase().includes(q)).slice(0,4).forEach(u=>items.push({icon:'bi-person',label:u.name,sub:u.id+' · '+u.dept,go:`#/users?id=${u.id}`}));db.get('alerts').filter(a=>[a.title,a.id].join(' ').toLowerCase().includes(q)).slice(0,4).forEach(a=>items.push({icon:'bi-exclamation-triangle',label:a.title,sub:a.id,go:`#/alerts?id=${a.id}`}));db.get('investigations').filter(i=>[i.title,i.id].join(' ').toLowerCase().includes(q)).slice(0,4).forEach(i=>items.push({icon:'bi-search',label:i.title,sub:i.id,go:`#/investigations?id=${i.id}`}));}document.getElementById('cmdResults').innerHTML=items.length?items.slice(0,14).map(i=>`<div class="command-item" onclick="location.hash='${i.go}';document.getElementById('cmd').remove()"><i class="bi ${i.icon} me-2"></i><b>${esc(i.label)}</b><span class="small-muted ms-2">${esc(i.sub)}</span></div>`).join(''):'<div class="empty">No command found.</div>';};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand();}if(e.key==='Escape'){document.getElementById('cmd')?.remove();window.closeSidebar&&window.closeSidebar();}});

function timelineItem(a,clickable=false){return `<div class="tl-item" ${clickable?`onclick='window.activityDetail(${JSON.stringify(a)})' style="cursor:pointer"`:''}><div class="tl-time">${a.time} · ${a.type}</div><div class="fw-semibold">${esc(a.title)}</div><div class="small-muted">${esc(a.detail)}</div></div>`;}
function simpleTable(headers,rows,clickable=false,handler=''){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr ${clickable?`onclick="window.${handler}('${String(r[0]).replace(/'/g,"\\'")}')" style="cursor:pointer"`:''}>${r.map((v,i)=>`<td>${i===0?`<b>${esc(v)}</b>`:esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function objectTable(rows){if(!rows.length)return '<div class="empty">No data.</div>';const keys=Object.keys(rows[0]).slice(0,8);return `<div class="table-wrap"><table class="table"><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${esc(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function fileTable(files){return `<div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>File</th><th>Operation</th><th>Size</th><th>Classification</th><th>Destination</th><th>Hash</th></tr></thead><tbody>${files.map(f=>`<tr><td>${f.time}</td><td><b>${esc(f.name)}</b><div class="small-muted">${esc(f.path)}</div></td><td>${badge(f.operation,f.operation==='COPY'||f.operation==='UPLOAD'?'risk-high':'status-online')}</td><td>${f.size}</td><td>${f.classification}</td><td>${f.destination}</td><td><span class="code-chip">${f.hash}</span></td></tr>`).join('')}</tbody></table></div>`;}
function fileLineage(files){const lin=files[0]?.lineage;if(!lin)return '';return `<div class="card-soft p-3 mb-3 bg-light"><b>File Lineage — ${lin}</b><div class="lineage-flow mt-3">${files.map((f,i)=>`${i?'<i class="bi bi-arrow-right"></i>':''}<span><b>${esc(f.name)}</b><small>${f.operation}</small></span>`).join('')}</div></div>`;}

function drawDashboardCharts(){destroyCharts();if(typeof Chart==='undefined')return;const r=document.getElementById('riskChart');if(r)charts.push(new Chart(r,{type:'line',data:{labels:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],datasets:[{label:'High-risk users',data:[8,9,8,11,13,12,17],tension:.35},{label:'Critical alerts',data:[2,3,2,4,5,3,6],tension:.35}]},options:{responsive:true,plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true}}}}));const sig=document.getElementById('signalChart');if(sig)charts.push(new Chart(sig,{type:'doughnut',data:{labels:['File','Identity','USB','Cloud','AI'],datasets:[{data:[32,18,20,17,13]}]},options:{plugins:{legend:{position:'bottom'}}}}));const w=document.getElementById('workChart');if(w){const d=db.get('work');charts.push(new Chart(w,{type:'bar',data:{labels:d.map(x=>x.dept),datasets:[{label:'Productivity %',data:d.map(x=>x.prod)},{label:'Overtime %',data:d.map(x=>x.overtime)}]},options:{plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true,max:100}}}}));}}
function render(){destroyCharts();if(!sessionStorage.getItem('ussLogged'))return login();let r=route(),allowed=roleRoutes[db.persona()]||[];if(!allowed.includes(r))r='dashboard';if(window.USSV3&&window.USSV3.routes[r]){const innerHold={};window.__ussRenderShell=(html)=>{shell(html);};window.__ussDb=db;return window.USSV3.routes[r]();}if(r==='dashboard')dashboard();else if(r==='tenants')tenants();else if(r==='organization')organization();else if(r==='users'){const id=params().get('id');id?userDetail(id):users();}else if(r==='devices')devices();else if(r==='activity')activity();else if(r==='workforce')workforce();else if(r==='risk')risk();else if(r==='alerts')alerts();else if(r==='dlp')dlp();else if(r==='policies')policies();else if(r==='investigations')investigations();else if(r==='reports')reports();else if(r==='ai')ai();else if(r==='privacy')privacy();else if(r==='audit')audit();else if(r==='integrations')integrations();else if(r==='transparency')transparency();else if(r==='settings')settings();else dashboard();}
window.closeModal=closeModal;window.toast=toast;window.render=render;window.addEventListener('hashchange',render);render();
})();
